(window.__qhadithX=window.__qhadithX||{})[44]={"1":[{"c":"Sunan Abu Dawud","r":"Hadith 1401","u":"https://quranx.com/Hadith/AbuDawud/DarusSalam/Hadith-1401","x":"Narrated Amr ibn al-'As:\n\nThe Prophet (ﷺ) taught me fifteen prostrations while reciting the Qur'an, including three in al-Mufassal and two in Surah al-Hajj. Abu Dawud said: Abu al-Darda' has reported eleven prostrations from the Prophet (ﷺ), but chain of this tradition is weak.","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ عَبْدِ الرَّحِيمِ بْنِ الْبَرْقِيِّ، حَدَّثَنَا ابْنُ أَبِي مَرْيَمَ، أَخْبَرَنَا نَافِعُ بْنُ يَزِيدَ، عَنِ الْحَارِثِ بْنِ سَعِيدٍ الْعُتَقِيِّ، عَنْ عَبْدِ اللَّهِ بْنِ مُنَيْنٍ، - مِنْ بَنِي عَبْدِ كُلاَلٍ - عَنْ عَمْرِو بْنِ الْعَاصِ، أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم أَقْرَأَهُ خَمْسَ عَشْرَةَ سَجْدَةً فِي الْقُرْآنِ مِنْهَا ثَلاَثٌ فِي الْمُفَصَّلِ وَفِي سُورَةِ الْحَجِّ سَجْدَتَانِ ‏.‏ قَالَ أَبُو دَاوُدَ رُوِيَ عَنْ أَبِي الدَّرْدَاءِ عَنِ النَّبِيِّ صلى الله عليه وسلم إِحْدَى عَشْرَةَ سَجْدَةً وَإِسْنَادُهُ وَاهٍ ‏.‏","v":[]}],"10":[{"c":"Sahih Bukhari","r":"Hadith 1007","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-1007","x":"Narrated Masruq:\n\nWe were with `Abdullah and he said, \"When the Prophet (ﷺ) saw the refusal of the people to accept Islam he said, \"O Allah! Send (famine) years on them for (seven years) like the seven years (of famine during the time) of (Prophet) Joseph.\" So famine overtook them for one year and destroyed every kind of life to such an extent that the people started eating hides, carcasses and rotten dead animals. Whenever one of them looked towards the sky, he would (imagine himself to) see smoke because of hunger. So Abu Sufyan went to the Prophet (ﷺ) and said, \"O Muhammad! You order people to obey Allah and to keep good relations with kith and kin. No doubt the people of your tribe are dying, so please pray to Allah for them.\" So Allah revealed: \"Then watch you For the day that The sky will bring forth a kind Of smoke Plainly visible... Verily! You will return (to disbelief) On the day when We shall seize You with a mighty grasp. (44.10-16) Ibn Mas`ud added, \"Al-Batsha (i.e. grasp) happened in the battle of Badr and no doubt smoke, Al-Batsha, Al-Lizam, and the verse of Surat Ar-Rum have all passed.","ar":"حَدَّثَنَا عُثْمَانُ بْنُ أَبِي شَيْبَةَ، قَالَ حَدَّثَنَا جَرِيرٌ، عَنْ مَنْصُورٍ، عَنْ أَبِي الضُّحَى، عَنْ مَسْرُوقٍ، قَالَ كُنَّا عِنْدَ عَبْدِ اللَّهِ فَقَالَ إِنَّ النَّبِيَّ صلى الله عليه وسلم لَمَّا رَأَى مِنَ النَّاسِ إِدْبَارًا قَالَ ‏\"‏ اللَّهُمَّ سَبْعٌ كَسَبْعِ يُوسُفَ ‏\"‏‏.‏ فَأَخَذَتْهُمْ سَنَةٌ حَصَّتْ كُلَّ شَىْءٍ حَتَّى أَكَلُوا الْجُلُودَ وَالْمَيْتَةَ وَالْجِيَفَ، وَيَنْظُرَ أَحَدُهُمْ إِلَى السَّمَاءِ فَيَرَى الدُّخَانَ مِنَ الْجُوعِ، فَأَتَاهُ أَبُو سُفْيَانَ فَقَالَ يَا مُحَمَّدُ إِنَّكَ تَأْمُرُ بِطَاعَةِ اللَّهِ وَبِصِلَةِ الرَّحِمِ وَإِنَّ قَوْمَكَ قَدْ هَلَكُوا، فَادْعُ اللَّهَ لَهُمْ قَالَ اللَّهُ تَعَالَى ‏{‏فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ‏}‏ إِلَى قَوْلِهِ ‏{‏عَائِدُونَ * يَوْمَ نَبْطِشُ الْبَطْشَةَ الْكُبْرَى‏}‏ فَالْبَطْشَةُ يَوْمَ بَدْرٍ، وَقَدْ مَضَتِ الدُّخَانُ وَالْبَطْشَةُ وَاللِّزَامُ وَآيَةُ الرُّومِ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 1020","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-1020","x":"Narrated Masruq:\n\nOne day I went to Ibn Mas`ud who said, \"When Quraish delayed in embracing Islam, the Prophet (ﷺ) I invoked Allah to curse them, so they were afflicted with a (famine) year because of which many of them died and they ate the carcasses and Abu Sufyan came to the Prophet (ﷺ) and said, 'O Muhammad! You came to order people to keep good relation with kith and kin and your nation is being destroyed, so invoke Allah I ? So the Prophet (ﷺ) I recited the Holy verses of Sirat-Ad-Dukhan: 'Then watch you For the day that The sky will Bring forth a kind Of smoke Plainly visible.' (44.10) When the famine was taken off, the people renegade once again as nonbelievers. The statement of Allah, (in Sura \"Ad- Dukhan\"-44) refers to that: 'On the day when We shall seize You with a mighty grasp.' (44.16) And that was what happened on the day of the battle of Badr.\" Asbath added on the authority of Mansur, \"Allah's Messenger (ﷺ) prayed for them and it rained heavily for seven days. So the people complained of the excessive rain. The Prophet (ﷺ) said, 'O Allah! (Let it rain) around us and not on us.' So the clouds dispersed over his head and it rained over the surroundings.\"","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ كَثِيرٍ، عَنْ سُفْيَانَ، حَدَّثَنَا مَنْصُورٌ، وَالأَعْمَشُ، عَنْ أَبِي الضُّحَى، عَنْ مَسْرُوقٍ، قَالَ أَتَيْتُ ابْنَ مَسْعُودٍ فَقَالَ إِنَّ قُرَيْشًا أَبْطَئُوا عَنِ الإِسْلاَمِ،، فَدَعَا عَلَيْهِمُ النَّبِيُّ صلى الله عليه وسلم فَأَخَذَتْهُمْ سَنَةٌ حَتَّى هَلَكُوا فِيهَا وَأَكَلُوا الْمَيْتَةَ وَالْعِظَامَ، فَجَاءَهُ أَبُو سُفْيَانَ فَقَالَ يَا مُحَمَّدُ، جِئْتَ تَأْمُرُ بِصِلَةِ الرَّحِمِ، وَإِنَّ قَوْمَكَ هَلَكُوا، فَادْعُ اللَّهَ‏.‏ فَقَرَأَ ‏{‏فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ‏}‏ ثُمَّ عَادُوا إِلَى كُفْرِهِمْ فَذَلِكَ قَوْلُهُ تَعَالَى ‏{‏يَوْمَ نَبْطِشُ الْبَطْشَةَ الْكُبْرَى‏}‏ يَوْمَ بَدْرٍ‏.‏ قَالَ وَزَادَ أَسْبَاطٌ عَنْ مَنْصُورٍ فَدَعَا رَسُولُ اللَّهِ صلى الله عليه وسلم، فَسُقُوا الْغَيْثَ، فَأَطْبَقَتْ عَلَيْهِمْ سَبْعًا، وَشَكَا النَّاسُ كَثْرَةَ الْمَطَرِ فَقَالَ ‏\"‏ اللَّهُمَّ حَوَالَيْنَا وَلاَ عَلَيْنَا ‏\"‏‏.‏ فَانْحَدَرَتِ السَّحَابَةُ عَنْ رَأْسِهِ، فَسُقُوا النَّاسُ حَوْلَهُمْ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4693","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4693","x":"Narrated `Abdullah (bin Mas`ud):\n\nWhen the Prophet (ﷺ) realized that the Quraish had delayed in embracing Islam, he said, \"O Allah! Protect me against their evil by afflicting them with seven (years of famine) like the seven years of (Prophet) Joseph.\" So they were struck with a year of famine that destroyed everything till they had to eat bones, and till a man would look towards the sky and see something like smoke between him and it. Allah said:-- \"Then watch you (O Muhammad) for the day when the sky will produce a kind of smoke plainly visible.\" (44.10) And Allah further said:-- \"Verily! We shall withdraw the punishment a little, Verily you will return (to disbelief).\" (44.15) (Will Allah relieve them from torture on the Day of Resurrection?) (The punishment of) the smoke had passed and Al-Baltsha (the destruction of the pagans in the Badr battle) had passed too.","ar":"حَدَّثَنَا الْحُمَيْدِيُّ، حَدَّثَنَا سُفْيَانُ، عَنِ الأَعْمَشِ، عَنْ مُسْلِمٍ، عَنْ مَسْرُوقٍ، عَنْ عَبْدِ اللَّهِ ـ رضى الله عنه ـ أَنَّ قُرَيْشًا لَمَّا أَبْطَئُوا عَنِ النَّبِيِّ صلى الله عليه وسلم بِالإِسْلاَمِ قَالَ ‏\"‏ اللَّهُمَّ اكْفِنِيهِمْ بِسَبْعٍ كَسَبْعِ يُوسُفَ ‏\"‏ فَأَصَابَتْهُمْ سَنَةٌ حَصَّتْ كُلَّ شَىْءٍ حَتَّى أَكَلُوا الْعِظَامَ حَتَّى جَعَلَ الرَّجُلُ يَنْظُرُ إِلَى السَّمَاءِ فَيَرَى بَيْنَهُ وَبَيْنَهَا مِثْلَ الدُّخَانِ قَالَ اللَّهُ ‏{‏فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ‏}‏ قَالَ اللَّهُ ‏{‏إِنَّا كَاشِفُو الْعَذَابِ قَلِيلاً إِنَّكُمْ عَائِدُونَ‏}‏ أَفَيُكْشَفُ عَنْهُمُ الْعَذَابُ يَوْمَ الْقِيَامَةِ، وَقَدْ مَضَى الدُّخَانُ وَمَضَتِ الْبَطْشَةُ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4774","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4774","x":"Narrated Masruq:\n\nWhile a man was delivering a speech in the tribe of Kinda, he said, \"Smoke will prevail on the Day of Resurrection and will deprive the hypocrites their faculties of hearing and seeing. The believers will be afflicted with something like cold only thereof.\" That news scared us, so I went to (Abdullah) Ibn Mas`ud while he was reclining (and told him the story) whereupon he became angry, sat up and said, \"He who knows a thing can say, it, but if he does not know, he should say, 'Allah knows best,' for it is an aspect of knowledge to say, 'I do not know,' if you do not know a certain thing. Allah said to His prophet. 'Say (O Muhammad): No wage do I ask of you for this (Qur'an), nor I am one of the pretenders (a person who pretends things which do not exist.)' (38.86) The Qur'aish delayed in embracing Islam for a period, so the Prophet (ﷺ) invoked evil on them, saying, 'O Allah! Help me against them by sending seven years of (famine) like those of Joseph.' So they were afflicted with such a severe year of famine that they were destroyed therein and ate dead animals and bones. They started seeing something like smoke between the sky and the earth (because of severe hunger). Abu Sufyan then came (to the Prophet) and said, \"O Muhammad! You came to order us for to keep good relations with Kith and kin, and your kinsmen have now perished, so please invoke Allah (to relieve them).' Then Ibn Mas`ud recited:-- 'Then watch you for the day that the sky will bring forth a kind of smoke plainly visible....but truly you will return! (to disbelief) (44.10-15) Ibn Mas`ud added, Then the punishment was stopped, but truly, they reverted to heathenism (their old way). So Allah (threatened them thus): 'On the day when we shall seize you with a mighty grasp.' (44.16) And that was the day of the Battle of Badr. Allah's saying- \"Lizama\" (the punishment) refers to the day of Badr Allah's Statement: Alif-Lam-Mim, the Romans have been defeated, and they, after their defeat, will be victorious,' (30.1- 3) (This verse): Indicates that the defeat of Byzantine has already passed.","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ كَثِيرٍ، حَدَّثَنَا سُفْيَانُ، حَدَّثَنَا مَنْصُورٌ، وَالأَعْمَشُ، عَنْ أَبِي الضُّحَى، عَنْ مَسْرُوقٍ، قَالَ بَيْنَمَا رَجُلٌ يُحَدِّثُ فِي كِنْدَةَ فَقَالَ يَجِيءُ دُخَانٌ يَوْمَ الْقِيَامَةِ فَيَأْخُذُ بِأَسْمَاعِ الْمُنَافِقِينَ وَأَبْصَارِهِمْ، يَأْخُذُ الْمُؤْمِنَ كَهَيْئَةِ الزُّكَامِ‏.‏ فَفَزِعْنَا، فَأَتَيْتُ ابْنَ مَسْعُودٍ، وَكَانَ مُتَّكِئًا، فَغَضِبَ فَجَلَسَ فَقَالَ مَنْ عَلِمَ فَلْيَقُلْ، وَمَنْ لَمْ يَعْلَمْ فَلْيَقُلِ اللَّهُ أَعْلَمُ‏.‏ فَإِنَّ مِنَ الْعِلْمِ أَنْ يَقُولَ لِمَا لاَ يَعْلَمُ لاَ أَعْلَمُ‏.‏ فَإِنَّ اللَّهَ قَالَ لِنَبِيِّهِ صلى الله عليه وسلم ‏{‏قُلْ مَا أَسْأَلُكُمْ عَلَيْهِ مِنْ أَجْرٍ وَمَا أَنَا مِنَ الْمُتَكَلِّفِينَ‏}‏ وَإِنَّ قُرَيْشًا أَبْطَئُوا عَنِ الإِسْلاَمِ فَدَعَا عَلَيْهِمِ النَّبِيُّ صلى الله عليه وسلم فَقَالَ ‏\"‏ اللَّهُمَّ أَعِنِّي عَلَيْهِمْ بِسَبْعٍ كَسَبْعِ يُوسُفَ، فَأَخَذَتْهُمْ سَنَةٌ حَتَّى هَلَكُوا فِيهَا، وَأَكَلُوا الْمَيْتَةَ وَالْعِظَامَ وَيَرَى الرَّجُلُ مَا بَيْنَ السَّمَاءِ وَالأَرْضِ كَهَيْئَةِ الدُّخَانِ ‏\"‏، فَجَاءَهُ أَبُو سُفْيَانَ فَقَالَ يَا مُحَمَّدُ جِئْتَ تَأْمُرُنَا بِصِلَةِ الرَّحِمِ، وَإِنَّ قَوْمَكَ قَدْ هَلَكُوا فَادْعُ اللَّهَ، فَقَرَأَ ‏{‏فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ‏}‏ إِلَى قَوْلِهِ ‏{‏عَائِدُونَ‏}‏ أَفَيُكْشَفُ عَنْهُمْ عَذَابُ الآخِرَةِ إِذَا جَاءَ ثُمَّ عَادُوا إِلَى كُفْرِهِمْ فَذَلِكَ قَوْلُهُ تَعَالَى ‏{‏يَوْمَ نَبْطِشُ الْبَطْشَةَ الْكُبْرَى‏}‏ يَوْمَ بَدْرٍ وَلِزَامًا يَوْمَ بَدْرٍ ‏{‏الم * غُلِبَتِ الرُّومُ‏}‏ إِلَى ‏{‏سَيَغْلِبُونَ‏}‏ وَالرُّومُ قَدْ مَضَى‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4809","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4809","x":"Narrated Masruq:\n\nWe came upon `Abdullah bin Mas`ud and he said \"O people! If somebody knows something, he can say it, but if he does not know it, he should say, \"Allah knows better,' for it is a sign of having knowledge to say about something which one does not know, 'Allah knows better.' Allah said to His Prophet: 'Say (O Muhammad ! ) No wage do I ask of You for this (Qur'an) nor am I one of the pretenders (a person who pretends things which do not exist).' (38.86) Now I will tell you about Ad- Dukhan (the smoke), Allah's Messenger (ﷺ) invited the Quraish to embrace Islam, but they delayed their response. So he said, \"O Allah! Help me against them by sending on them seven years of famine similar to the seven years of famine of Joseph.\" So the famine year overtook them and everything was destroyed till they ate dead animals and skins. People started imagining to see smoke between them and the sky because of severe hunger. Allah said: 'Then watch you for the Day that the sky will bring forth a kind of smoke plainly visible, covering the people... This is painful torment.' (44.10-11) (So they invoked Allah) \"Our Lord! Remove the punishment from us really we are believers.\" How can there be an (effectual) reminder for them when an Apostle, explaining things clearly, has already come to them? Then they had turned away from him and said: 'One taught (by a human being), a madman?' 'We shall indeed remove punishment for a while, but truly, you will revert (to disbelief).' (44.12-15) Will the punishment be removed on the Day of Resurrection?\" `Abdullah added, \"The punishment was removed from them for a while but they reverted to disbelief, so Allah destroyed them on the Day of Badr. Allah said: 'The day We shall seize you with a mighty grasp. We will indeed (then) exact retribution.\" (44.16)","ar":"حَدَّثَنَا قُتَيْبَةُ، حَدَّثَنَا جَرِيرٌ، عَنِ الأَعْمَشِ، عَنْ أَبِي الضُّحَى، عَنْ مَسْرُوقٍ، قَالَ دَخَلْنَا عَلَى عَبْدِ اللَّهِ بْنِ مَسْعُودٍ، قَالَ يَا أَيُّهَا النَّاسُ مَنْ عَلِمَ شَيْئًا فَلْيَقُلْ بِهِ، وَمَنْ لَمْ يَعْلَمْ فَلْيَقُلِ اللَّهُ أَعْلَمُ، فَإِنَّ مِنَ الْعِلْمِ أَنْ يَقُولَ لِمَا لاَ يَعْلَمُ اللَّهُ أَعْلَمُ، قَالَ اللَّهُ عَزَّ وَجَلَّ لِنَبِيِّهِ صلى الله عليه وسلم ‏{‏قُلْ مَا أَسْأَلُكُمْ عَلَيْهِ مِنْ أَجْرٍ وَمَا أَنَا مِنَ الْمُتَكَلِّفِينَ‏}‏ وَسَأُحَدِّثُكُمْ عَنِ الدُّخَانِ إِنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم دَعَا قُرَيْشًا إِلَى الإِسْلاَمِ فَأَبْطَئُوا عَلَيْهِ فَقَالَ ‏\"‏ اللَّهُمَّ أَعِنِّي عَلَيْهِمْ بِسَبْعٍ كَسَبْعِ يُوسُفَ ‏\"‏، فَأَخَذَتْهُمْ سَنَةٌ فَحَصَّتْ كُلَّ شَىْءٍ حَتَّى أَكَلُوا الْمَيْتَةَ وَالْجُلُودَ حَتَّى جَعَلَ الرَّجُلُ يَرَى بَيْنَهُ وَبَيْنَ السَّمَاءِ دُخَانًا مِنَ الْجُوعِ، قَالَ اللَّهُ عَزَّ وَجَلَّ ‏{‏فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ * يَغْشَى النَّاسَ هَذَا عَذَابٌ أَلِيمٌ‏}‏ قَالَ فَدَعَوْا ‏{‏رَبَّنَا اكْشِفْ عَنَّا الْعَذَابَ إِنَّا مُؤْمِنُونَ * أَنَّى لَهُمُ الذِّكْرَى وَقَدْ جَاءَهُمْ رَسُولٌ مُبِينٌ * ثُمَّ تَوَلَّوْا عَنْهُ وَقَالُوا مُعَلَّمٌ مَجْنُونٌ * إِنَّا كَاشِفُو الْعَذَابِ قَلِيلاً إِنَّكُمْ عَائِدُونَ‏}‏ أَفَيُكْشَفُ الْعَذَابُ يَوْمَ الْقِيَامَةِ قَالَ فَكُشِفَ ثُمَّ عَادُوا فِي كُفْرِهِمْ، فَأَخَذَهُمُ اللَّهُ يَوْمَ بَدْرٍ قَالَ اللَّهُ تَعَالَى ‏{‏يَوْمَ نَبْطِشُ الْبَطْشَةَ الْكُبْرَى إِنَّا مُنْتَقِمُونَ‏}‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4821","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4821","x":"Narrated `Abdullah:\n\nIt (i.e., the imagined smoke) was because, when the Quraish refused to obey the Prophet, he asked Allah to afflict them with years of famine similar to those of (Prophet) Joseph. So they were stricken with famine and fatigue, so much so that they ate even bones. A man would look towards the sky and imagine seeing something like smoke between him and the sky because of extreme fatigue. So Allah revealed:-- 'Then watch you for the Day that the sky will bring forth a kind of smoke plainly visible, covering the people; this is a painfull of torment.' (44.10-11) Then someone (Abu Sufyan) came to Allah's Messenger (ﷺ) and said, \"O Allah's Messenger (ﷺ)! Invoke Allah to send rain for the tribes of Mudar for they are on the verge of destruction.\" On that the Prophet (ﷺ) said (astonishingly) \"Shall I invoke Allah) for the tribes of Mudar? Verily, you are a brave man!\" But the Prophet prayed for rain and it rained for them. Then the Verse was revealed. 'But truly you will return (to disbelief).' (44.15) (When the famine was over and) they restored prosperity and welfare, they reverted to their ways (of heathenism) whereupon Allah revealed: 'On the Day when We shall seize you with a Mighty Grasp. We will indeed (then) exact retribution.' (44.16) The narrator said, \"That was the day of the Battle of Badr.\"","ar":"حَدَّثَنَا يَحْيَى، حَدَّثَنَا أَبُو مُعَاوِيَةَ، عَنِ الأَعْمَشِ، عَنْ مُسْلِمٍ، عَنْ مَسْرُوقٍ، قَالَ قَالَ عَبْدُ اللَّهِ إِنَّمَا كَانَ هَذَا لأَنَّ قُرَيْشًا لَمَّا اسْتَعْصَوْا عَلَى النَّبِيِّ صلى الله عليه وسلم دَعَا عَلَيْهِمْ بِسِنِينَ كَسِنِي يُوسُفَ، فَأَصَابَهُمْ قَحْطٌ وَجَهْدٌ حَتَّى أَكَلُوا الْعِظَامَ، فَجَعَلَ الرَّجُلُ يَنْظُرُ إِلَى السَّمَاءِ فَيَرَى مَا بَيْنَهُ وَبَيْنَهَا كَهَيْئَةِ الدُّخَانِ مِنَ الْجَهْدِ، فَأَنْزَلَ اللَّهُ تَعَالَى ‏{‏فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ * يَغْشَى النَّاسَ هَذَا عَذَابٌ أَلِيمٌ‏}‏ قَالَ فَأُتِيَ رَسُولُ اللَّهِ صلى الله عليه وسلم فَقِيلَ يَا رَسُولَ اللَّهِ اسْتَسْقِ اللَّهَ لِمُضَرَ، فَإِنَّهَا قَدْ هَلَكَتْ‏.‏ قَالَ ‏\"‏ لِمُضَرَ إِنَّكَ لَجَرِيءٌ ‏\"‏‏.‏ فَاسْتَسْقَى فَسُقُوا‏.‏ فَنَزَلَتْ ‏{‏إِنَّكُمْ عَائِدُونَ‏}‏ فَلَمَّا أَصَابَتْهُمُ الرَّفَاهِيَةُ عَادُوا إِلَى حَالِهِمْ حِينَ أَصَابَتْهُمُ الرَّفَاهِيَةُ‏.‏ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏{‏يَوْمَ نَبْطِشُ الْبَطْشَةَ الْكُبْرَى إِنَّا مُنْتَقِمُونَ‏}‏ قَالَ يَعْنِي يَوْمَ بَدْرٍ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4822","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4822","x":"Narrated `Abdullah:\n\nIt is a sign of having knowledge that, when you do not know something, you say: 'Allah knows better.' Allah said to his Prophet: 'Say: No wage do I ask of you for this (Qur'an), nor am I one of the pretenders (a person who pretends things which do not exist)' (38.86) When the Quraish troubled and stood against the Prophet (ﷺ) he said, \"O Allah! Help me against them by afflicting them with seven years of famine like the seven years of Joseph.\" So they were stricken with a year of famine during which they ate bones and dead animals because of too much suffering, and one of them would see something like smoke between him and the sky because of hunger. Then they said: Our Lord! Remove the torment from us, really we are believers. (44.12) And then it was said to the Prophet (by Allah), \"If we remove it from them. they will revert to their ways (of heathenism).\" So the Prophet (ﷺ) invoked his Lord, who removed the punishment from them, but later they reverted (to heathenism), whereupon Allah punished them on the day of the Battle of Badr, and that is what Allah's Statement indicates: 'Then watch for the day that the sky will bring forth a kind of smoke plainly visible...we will indeed (then) exact retribution.' (44.10).","ar":"حَدَّثَنَا يَحْيَى، حَدَّثَنَا وَكِيعٌ، عَنِ الأَعْمَشِ، عَنْ أَبِي الضُّحَى، عَنْ مَسْرُوقٍ، قَالَ دَخَلْتُ عَلَى عَبْدِ اللَّهِ فَقَالَ إِنَّ مِنَ الْعِلْمِ أَنْ تَقُولَ لِمَا لاَ تَعْلَمُ اللَّهُ أَعْلَمُ، إِنَّ اللَّهَ قَالَ لِنَبِيِّهِ صلى الله عليه وسلم ‏{‏قُلْ مَا أَسْأَلُكُمْ عَلَيْهِ مِنْ أَجْرٍ وَمَا أَنَا مِنَ الْمُتَكَلِّفِينَ‏}‏ إِنَّ قُرَيْشًا لَمَّا غَلَبُوا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَاسْتَعْصَوْا عَلَيْهِ قَالَ اللَّهُمَّ أَعِنِّي عَلَيْهِمْ بِسَبْعٍ كَسَبْعِ يُوسُفَ فَأَخَذَتْهُمْ سَنَةٌ أَكَلُوا فِيهَا الْعِظَامَ وَالْمَيْتَةَ مِنْ الْجَهْدِ حَتَّى جَعَلَ أَحَدُهُمْ يَرَى مَا بَيْنَهُ وَبَيْنَ السَّمَاءِ كَهَيْئَةِ الدُّخَانِ مِنْ الْجُوعِ قَالُوا ￼ رَبَّنَا اكْشِفْ عَنَّا الْعَذَابَ إِنَّا مُؤْمِنُونَ ￼ فَقِيلَ لَهُ إِنْ كَشَفْنَا عَنْهُمْ عَادُوا فَدَعَا رَبَّهُ فَكَشَفَ عَنْهُمْ فَعَادُوا فَانْتَقَمَ اللَّهُ مِنْهُمْ يَوْمَ بَدْرٍ فَذَلِكَ قَوْلُهُ تَعَالَى ￼ فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ إِلَى قَوْلِهِ جَلَّ ذِكْرُهُ إِنَّا مُنْتَقِمُونَ.","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4823","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4823","x":"Narrated Masruq:\n\nI came upon `Abdullah and he said, \"When Allah's Messenger (ﷺ) invited Quraish (to Islam), they disbelieved him and stood against him. So he (the Prophet) said, \"O Allah! Help me against them by afflicting them with seven years of famine similar to the seven years of Joseph.' So they were stricken with a year of drought that destroyed everything, and they started eating dead animals, and if one of them got up he would see something like smoke between him and the sky from the severe fatigue and hunger.\" `Abdullah then recited:-- 'Then watch you for the Day that the sky will bring forth a kind of smoke plainly visible, covering the people. This is a painful torment... (till he reached)........ We shall indeed remove the punishment for a while, but truly you will revert (to heathenism): (44.10-15) `Abdullah added: \"Will the punishment be removed from them on the Day of Resurrection?\" He added,\" The severe grasp\" was the Day of the Battle of Badr.\"","ar":"حَدَّثَنَا سُلَيْمَانُ بْنُ حَرْبٍ، حَدَّثَنَا جَرِيرُ بْنُ حَازِمٍ، عَنِ الأَعْمَشِ، عَنْ أَبِي الضُّحَى، عَنْ مَسْرُوقٍ، قَالَ دَخَلْتُ عَلَى عَبْدِ اللَّهِ ثُمَّ قَالَ إِنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم لَمَّا دَعَا قُرَيْشًا كَذَّبُوهُ وَاسْتَعْصَوْا عَلَيْهِ فَقَالَ ‏\"‏ اللَّهُمَّ أَعِنِّي عَلَيْهِمْ بِسَبْعٍ كَسَبْعِ يُوسُفَ ‏\"‏‏.‏ فَأَصَابَتْهُمْ سَنَةٌ حَصَّتْ ـ يَعْنِي ـ كُلَّ شَىْءٍ حَتَّى كَانُوا يَأْكُلُونَ الْمَيْتَةَ فَكَانَ يَقُومُ أَحَدُهُمْ فَكَانَ يَرَى بَيْنَهُ وَبَيْنَ السَّمَاءِ مِثْلَ الدُّخَانِ مِنَ الْجَهْدِ وَالْجُوعِ ثُمَّ قَرَأَ ‏{‏فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ * يَغْشَى النَّاسَ هَذَا عَذَابٌ أَلِيمٌ‏}‏ حَتَّى بَلَغَ ‏{‏إِنَّا كَاشِفُو الْعَذَابِ قَلِيلاً إِنَّكُمْ عَائِدُونَ‏}‏ قَالَ عَبْدُ اللَّهِ أَفَيُكْشَفُ عَنْهُمُ الْعَذَابُ يَوْمَ الْقِيَامَةِ قَالَ وَالْبَطْشَةُ الْكُبْرَى يَوْمَ بَدْرٍ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3254","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3254","x":"Narrated Masruq:\n\n\"A man came to 'Abdullah and said: 'A story teller has said that a smoke will appear from the earth, taking the hearing of disbelievers and manifesting as a cold for the believers.'\" He became angry, and since he was reclining, he sat up then said: 'When one of you is asked about something he knows, then let him speak accordingly' - Mansur (one of the narrators) narrated it as: \"Then let him inform of it\" - \"And when asked about what he does not know, then let him say: \"Allah knows best.\" For indeed, it is part of a man's knowledge, that when he is asked about something he does not know, he says: \"Allah knows best.\" For verily Allah, Most High said to His Prophet: Say: \"No wage do I ask of you for this, nor am I one of the pretenders (38:86).\" When the Messenger of Allah (ﷺ) saw that the Quraish were behaving stubbornly with him, he said: \"O Allah! Assist me against them with seven (years of famine) like the seven of Yusuf.\" So He punished them with drought making everything barren, until they ate skins and carcasses\" - one of them said: \"bones.\" He said: 'And it appeared that smoke was coming out of the earth. So Abu Sufyan came to him and said: \"Verily your people are being destroyed, so supplicate to Allah for them.\" He said: \"So this is about His saying: 'The Day when the sky will bring forth a visible smoke, covering the people, this is a painful torment (44:10 & 11).'\" Mansur narrated it as: \"So this is about His saying: Our Lord! Remove the torment from us, really we shall become believers (44:12).\" - \"So shall the punishment be removed from them in the Hereafter? Al-Batshah (humiliated defeat in Badr), Al-Lizam (disbeliever captives from Badr), the smoke,\" - one of them said: \"The moon\" the other said: \"The Romans have all passed.\"","ar":"حَدَّثَنَا مَحْمُودُ بْنُ غَيْلاَنَ، حَدَّثَنَا عَبْدُ الْمَلِكِ بْنُ إِبْرَاهِيمَ الْجُدِّيُّ، حَدَّثَنَا شُعْبَةُ، عَنِ الأَعْمَشِ، وَمَنْصُورٍ، سَمِعَا أَبَا الضُّحَى، يُحَدِّثُ عَنْ مَسْرُوقٍ، قَالَ جَاءَ رَجُلٌ إِلَى عَبْدِ اللَّهِ فَقَالَ إِنَّ قَاصًّا يَقُصُّ يَقُولُ إِنَّهُ يَخْرُجُ مِنَ الأَرْضِ الدُّخَانُ فَيَأْخُذُ بِمَسَامِعِ الْكُفَّارِ وَيَأْخُذُ الْمُؤْمِنَ كَهَيْئَةِ الزُّكَامِ قَالَ فَغَضِبَ وَكَانَ مُتَّكِئًا فَجَلَسَ ثُمَّ قَالَ إِذَا سُئِلَ أَحَدُكُمْ عَمَّا يَعْلَمُ فَلْيَقُلْ بِهِ قَالَ مَنْصُورٌ فَلْيُخْبِرْ بِهِ وَإِذَا سُئِلَ عَمَّا لاَ يَعْلَمُ فَلْيَقُلِ اللَّهُ أَعْلَمُ فَإِنَّ مِنْ عِلْمِ الرَّجُلِ إِذَا سُئِلَ عَمَّا لاَ يَعْلَمُ أَنْ يَقُولَ اللَّهُ أَعْلَمُ فَإِنَّ اللَّهَ تَعَالَى قَالَ لِنَبِيِّهِ ‏:‏ ‏(‏قلْ مَا أَسْأَلُكُمْ عَلَيْهِ مِنْ أَجْرٍ وَمَا أَنَا مِنَ الْمُتَكَلِّفِينَ ‏)‏ ‏\"‏ ‏.‏ إِنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم لَمَّا رَأَى قُرَيْشًا اسْتَعْصَوْا عَلَيْهِ قَالَ ‏\"‏ اللَّهُمَّ أَعِنِّي عَلَيْهِمْ بِسَبْعٍ كَسَبْعِ يُوسُفَ ‏\"‏ ‏.‏ فَأَخَذَتْهُمْ سَنَةٌ فَأَحْصَتْ كُلَّ شَيْءٍ حَتَّى أَكَلُوا الْجُلُودَ وَالْمَيْتَةَ وَقَالَ أَحَدُهُمَا الْعِظَامَ قَالَ وَجَعَلَ يَخْرُجُ مِنَ الأَرْضِ كَهَيْئَةِ الدُّخَانِ قَالَ فَأَتَاهُ أَبُو سُفْيَانَ قَالَ إِنَّ قَوْمَكَ قَدْ هَلَكُوا فَادْعُ اللَّهَ لَهُمْ ‏.‏ قَالَ فَهَذَا لِقَوْلِهِ ‏:‏ ‏(‏ يوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ * يَغْشَى النَّاسَ هَذَا عَذَابٌ أَلِيمٌ ‏)‏ ‏.‏ قَالَ مَنْصُورٌ هَذَا لِقَوْلِهِ ‏(‏ رَبَّنَا اكْشِفْ عَنَّا الْعَذَابَ إِنَّا مُؤْمِنُونَ ‏)‏ فَهَلْ يُكْشَفُ عَذَابُ الآخِرَةِ قَالَ مَضَى الْبَطْشَةُ وَاللِّزَامُ الدُّخَانُ وَقَالَ أَحَدُهُمَا الْقَمَرُ وَقَالَ الآخَرُ الرُّومُ ‏.‏ قَالَ أَبُو عِيسَى وَاللِّزَامُ يَعْنِي يَوْمَ بَدْرٍ ‏.‏ قَالَ وَهَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏","v":[]}],"11":[{"c":"Sahih Bukhari","r":"Hadith 1007","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-1007","x":"Narrated Masruq:\n\nWe were with `Abdullah and he said, \"When the Prophet (ﷺ) saw the refusal of the people to accept Islam he said, \"O Allah! Send (famine) years on them for (seven years) like the seven years (of famine during the time) of (Prophet) Joseph.\" So famine overtook them for one year and destroyed every kind of life to such an extent that the people started eating hides, carcasses and rotten dead animals. Whenever one of them looked towards the sky, he would (imagine himself to) see smoke because of hunger. So Abu Sufyan went to the Prophet (ﷺ) and said, \"O Muhammad! You order people to obey Allah and to keep good relations with kith and kin. No doubt the people of your tribe are dying, so please pray to Allah for them.\" So Allah revealed: \"Then watch you For the day that The sky will bring forth a kind Of smoke Plainly visible... Verily! You will return (to disbelief) On the day when We shall seize You with a mighty grasp. (44.10-16) Ibn Mas`ud added, \"Al-Batsha (i.e. grasp) happened in the battle of Badr and no doubt smoke, Al-Batsha, Al-Lizam, and the verse of Surat Ar-Rum have all passed.","ar":"حَدَّثَنَا عُثْمَانُ بْنُ أَبِي شَيْبَةَ، قَالَ حَدَّثَنَا جَرِيرٌ، عَنْ مَنْصُورٍ، عَنْ أَبِي الضُّحَى، عَنْ مَسْرُوقٍ، قَالَ كُنَّا عِنْدَ عَبْدِ اللَّهِ فَقَالَ إِنَّ النَّبِيَّ صلى الله عليه وسلم لَمَّا رَأَى مِنَ النَّاسِ إِدْبَارًا قَالَ ‏\"‏ اللَّهُمَّ سَبْعٌ كَسَبْعِ يُوسُفَ ‏\"‏‏.‏ فَأَخَذَتْهُمْ سَنَةٌ حَصَّتْ كُلَّ شَىْءٍ حَتَّى أَكَلُوا الْجُلُودَ وَالْمَيْتَةَ وَالْجِيَفَ، وَيَنْظُرَ أَحَدُهُمْ إِلَى السَّمَاءِ فَيَرَى الدُّخَانَ مِنَ الْجُوعِ، فَأَتَاهُ أَبُو سُفْيَانَ فَقَالَ يَا مُحَمَّدُ إِنَّكَ تَأْمُرُ بِطَاعَةِ اللَّهِ وَبِصِلَةِ الرَّحِمِ وَإِنَّ قَوْمَكَ قَدْ هَلَكُوا، فَادْعُ اللَّهَ لَهُمْ قَالَ اللَّهُ تَعَالَى ‏{‏فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ‏}‏ إِلَى قَوْلِهِ ‏{‏عَائِدُونَ * يَوْمَ نَبْطِشُ الْبَطْشَةَ الْكُبْرَى‏}‏ فَالْبَطْشَةُ يَوْمَ بَدْرٍ، وَقَدْ مَضَتِ الدُّخَانُ وَالْبَطْشَةُ وَاللِّزَامُ وَآيَةُ الرُّومِ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 1020","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-1020","x":"Narrated Masruq:\n\nOne day I went to Ibn Mas`ud who said, \"When Quraish delayed in embracing Islam, the Prophet (ﷺ) I invoked Allah to curse them, so they were afflicted with a (famine) year because of which many of them died and they ate the carcasses and Abu Sufyan came to the Prophet (ﷺ) and said, 'O Muhammad! You came to order people to keep good relation with kith and kin and your nation is being destroyed, so invoke Allah I ? So the Prophet (ﷺ) I recited the Holy verses of Sirat-Ad-Dukhan: 'Then watch you For the day that The sky will Bring forth a kind Of smoke Plainly visible.' (44.10) When the famine was taken off, the people renegade once again as nonbelievers. The statement of Allah, (in Sura \"Ad- Dukhan\"-44) refers to that: 'On the day when We shall seize You with a mighty grasp.' (44.16) And that was what happened on the day of the battle of Badr.\" Asbath added on the authority of Mansur, \"Allah's Messenger (ﷺ) prayed for them and it rained heavily for seven days. So the people complained of the excessive rain. The Prophet (ﷺ) said, 'O Allah! (Let it rain) around us and not on us.' So the clouds dispersed over his head and it rained over the surroundings.\"","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ كَثِيرٍ، عَنْ سُفْيَانَ، حَدَّثَنَا مَنْصُورٌ، وَالأَعْمَشُ، عَنْ أَبِي الضُّحَى، عَنْ مَسْرُوقٍ، قَالَ أَتَيْتُ ابْنَ مَسْعُودٍ فَقَالَ إِنَّ قُرَيْشًا أَبْطَئُوا عَنِ الإِسْلاَمِ،، فَدَعَا عَلَيْهِمُ النَّبِيُّ صلى الله عليه وسلم فَأَخَذَتْهُمْ سَنَةٌ حَتَّى هَلَكُوا فِيهَا وَأَكَلُوا الْمَيْتَةَ وَالْعِظَامَ، فَجَاءَهُ أَبُو سُفْيَانَ فَقَالَ يَا مُحَمَّدُ، جِئْتَ تَأْمُرُ بِصِلَةِ الرَّحِمِ، وَإِنَّ قَوْمَكَ هَلَكُوا، فَادْعُ اللَّهَ‏.‏ فَقَرَأَ ‏{‏فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ‏}‏ ثُمَّ عَادُوا إِلَى كُفْرِهِمْ فَذَلِكَ قَوْلُهُ تَعَالَى ‏{‏يَوْمَ نَبْطِشُ الْبَطْشَةَ الْكُبْرَى‏}‏ يَوْمَ بَدْرٍ‏.‏ قَالَ وَزَادَ أَسْبَاطٌ عَنْ مَنْصُورٍ فَدَعَا رَسُولُ اللَّهِ صلى الله عليه وسلم، فَسُقُوا الْغَيْثَ، فَأَطْبَقَتْ عَلَيْهِمْ سَبْعًا، وَشَكَا النَّاسُ كَثْرَةَ الْمَطَرِ فَقَالَ ‏\"‏ اللَّهُمَّ حَوَالَيْنَا وَلاَ عَلَيْنَا ‏\"‏‏.‏ فَانْحَدَرَتِ السَّحَابَةُ عَنْ رَأْسِهِ، فَسُقُوا النَّاسُ حَوْلَهُمْ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4774","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4774","x":"Narrated Masruq:\n\nWhile a man was delivering a speech in the tribe of Kinda, he said, \"Smoke will prevail on the Day of Resurrection and will deprive the hypocrites their faculties of hearing and seeing. The believers will be afflicted with something like cold only thereof.\" That news scared us, so I went to (Abdullah) Ibn Mas`ud while he was reclining (and told him the story) whereupon he became angry, sat up and said, \"He who knows a thing can say, it, but if he does not know, he should say, 'Allah knows best,' for it is an aspect of knowledge to say, 'I do not know,' if you do not know a certain thing. Allah said to His prophet. 'Say (O Muhammad): No wage do I ask of you for this (Qur'an), nor I am one of the pretenders (a person who pretends things which do not exist.)' (38.86) The Qur'aish delayed in embracing Islam for a period, so the Prophet (ﷺ) invoked evil on them, saying, 'O Allah! Help me against them by sending seven years of (famine) like those of Joseph.' So they were afflicted with such a severe year of famine that they were destroyed therein and ate dead animals and bones. They started seeing something like smoke between the sky and the earth (because of severe hunger). Abu Sufyan then came (to the Prophet) and said, \"O Muhammad! You came to order us for to keep good relations with Kith and kin, and your kinsmen have now perished, so please invoke Allah (to relieve them).' Then Ibn Mas`ud recited:-- 'Then watch you for the day that the sky will bring forth a kind of smoke plainly visible....but truly you will return! (to disbelief) (44.10-15) Ibn Mas`ud added, Then the punishment was stopped, but truly, they reverted to heathenism (their old way). So Allah (threatened them thus): 'On the day when we shall seize you with a mighty grasp.' (44.16) And that was the day of the Battle of Badr. Allah's saying- \"Lizama\" (the punishment) refers to the day of Badr Allah's Statement: Alif-Lam-Mim, the Romans have been defeated, and they, after their defeat, will be victorious,' (30.1- 3) (This verse): Indicates that the defeat of Byzantine has already passed.","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ كَثِيرٍ، حَدَّثَنَا سُفْيَانُ، حَدَّثَنَا مَنْصُورٌ، وَالأَعْمَشُ، عَنْ أَبِي الضُّحَى، عَنْ مَسْرُوقٍ، قَالَ بَيْنَمَا رَجُلٌ يُحَدِّثُ فِي كِنْدَةَ فَقَالَ يَجِيءُ دُخَانٌ يَوْمَ الْقِيَامَةِ فَيَأْخُذُ بِأَسْمَاعِ الْمُنَافِقِينَ وَأَبْصَارِهِمْ، يَأْخُذُ الْمُؤْمِنَ كَهَيْئَةِ الزُّكَامِ‏.‏ فَفَزِعْنَا، فَأَتَيْتُ ابْنَ مَسْعُودٍ، وَكَانَ مُتَّكِئًا، فَغَضِبَ فَجَلَسَ فَقَالَ مَنْ عَلِمَ فَلْيَقُلْ، وَمَنْ لَمْ يَعْلَمْ فَلْيَقُلِ اللَّهُ أَعْلَمُ‏.‏ فَإِنَّ مِنَ الْعِلْمِ أَنْ يَقُولَ لِمَا لاَ يَعْلَمُ لاَ أَعْلَمُ‏.‏ فَإِنَّ اللَّهَ قَالَ لِنَبِيِّهِ صلى الله عليه وسلم ‏{‏قُلْ مَا أَسْأَلُكُمْ عَلَيْهِ مِنْ أَجْرٍ وَمَا أَنَا مِنَ الْمُتَكَلِّفِينَ‏}‏ وَإِنَّ قُرَيْشًا أَبْطَئُوا عَنِ الإِسْلاَمِ فَدَعَا عَلَيْهِمِ النَّبِيُّ صلى الله عليه وسلم فَقَالَ ‏\"‏ اللَّهُمَّ أَعِنِّي عَلَيْهِمْ بِسَبْعٍ كَسَبْعِ يُوسُفَ، فَأَخَذَتْهُمْ سَنَةٌ حَتَّى هَلَكُوا فِيهَا، وَأَكَلُوا الْمَيْتَةَ وَالْعِظَامَ وَيَرَى الرَّجُلُ مَا بَيْنَ السَّمَاءِ وَالأَرْضِ كَهَيْئَةِ الدُّخَانِ ‏\"‏، فَجَاءَهُ أَبُو سُفْيَانَ فَقَالَ يَا مُحَمَّدُ جِئْتَ تَأْمُرُنَا بِصِلَةِ الرَّحِمِ، وَإِنَّ قَوْمَكَ قَدْ هَلَكُوا فَادْعُ اللَّهَ، فَقَرَأَ ‏{‏فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ‏}‏ إِلَى قَوْلِهِ ‏{‏عَائِدُونَ‏}‏ أَفَيُكْشَفُ عَنْهُمْ عَذَابُ الآخِرَةِ إِذَا جَاءَ ثُمَّ عَادُوا إِلَى كُفْرِهِمْ فَذَلِكَ قَوْلُهُ تَعَالَى ‏{‏يَوْمَ نَبْطِشُ الْبَطْشَةَ الْكُبْرَى‏}‏ يَوْمَ بَدْرٍ وَلِزَامًا يَوْمَ بَدْرٍ ‏{‏الم * غُلِبَتِ الرُّومُ‏}‏ إِلَى ‏{‏سَيَغْلِبُونَ‏}‏ وَالرُّومُ قَدْ مَضَى‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4809","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4809","x":"Narrated Masruq:\n\nWe came upon `Abdullah bin Mas`ud and he said \"O people! If somebody knows something, he can say it, but if he does not know it, he should say, \"Allah knows better,' for it is a sign of having knowledge to say about something which one does not know, 'Allah knows better.' Allah said to His Prophet: 'Say (O Muhammad ! ) No wage do I ask of You for this (Qur'an) nor am I one of the pretenders (a person who pretends things which do not exist).' (38.86) Now I will tell you about Ad- Dukhan (the smoke), Allah's Messenger (ﷺ) invited the Quraish to embrace Islam, but they delayed their response. So he said, \"O Allah! Help me against them by sending on them seven years of famine similar to the seven years of famine of Joseph.\" So the famine year overtook them and everything was destroyed till they ate dead animals and skins. People started imagining to see smoke between them and the sky because of severe hunger. Allah said: 'Then watch you for the Day that the sky will bring forth a kind of smoke plainly visible, covering the people... This is painful torment.' (44.10-11) (So they invoked Allah) \"Our Lord! Remove the punishment from us really we are believers.\" How can there be an (effectual) reminder for them when an Apostle, explaining things clearly, has already come to them? Then they had turned away from him and said: 'One taught (by a human being), a madman?' 'We shall indeed remove punishment for a while, but truly, you will revert (to disbelief).' (44.12-15) Will the punishment be removed on the Day of Resurrection?\" `Abdullah added, \"The punishment was removed from them for a while but they reverted to disbelief, so Allah destroyed them on the Day of Badr. Allah said: 'The day We shall seize you with a mighty grasp. We will indeed (then) exact retribution.\" (44.16)","ar":"حَدَّثَنَا قُتَيْبَةُ، حَدَّثَنَا جَرِيرٌ، عَنِ الأَعْمَشِ، عَنْ أَبِي الضُّحَى، عَنْ مَسْرُوقٍ، قَالَ دَخَلْنَا عَلَى عَبْدِ اللَّهِ بْنِ مَسْعُودٍ، قَالَ يَا أَيُّهَا النَّاسُ مَنْ عَلِمَ شَيْئًا فَلْيَقُلْ بِهِ، وَمَنْ لَمْ يَعْلَمْ فَلْيَقُلِ اللَّهُ أَعْلَمُ، فَإِنَّ مِنَ الْعِلْمِ أَنْ يَقُولَ لِمَا لاَ يَعْلَمُ اللَّهُ أَعْلَمُ، قَالَ اللَّهُ عَزَّ وَجَلَّ لِنَبِيِّهِ صلى الله عليه وسلم ‏{‏قُلْ مَا أَسْأَلُكُمْ عَلَيْهِ مِنْ أَجْرٍ وَمَا أَنَا مِنَ الْمُتَكَلِّفِينَ‏}‏ وَسَأُحَدِّثُكُمْ عَنِ الدُّخَانِ إِنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم دَعَا قُرَيْشًا إِلَى الإِسْلاَمِ فَأَبْطَئُوا عَلَيْهِ فَقَالَ ‏\"‏ اللَّهُمَّ أَعِنِّي عَلَيْهِمْ بِسَبْعٍ كَسَبْعِ يُوسُفَ ‏\"‏، فَأَخَذَتْهُمْ سَنَةٌ فَحَصَّتْ كُلَّ شَىْءٍ حَتَّى أَكَلُوا الْمَيْتَةَ وَالْجُلُودَ حَتَّى جَعَلَ الرَّجُلُ يَرَى بَيْنَهُ وَبَيْنَ السَّمَاءِ دُخَانًا مِنَ الْجُوعِ، قَالَ اللَّهُ عَزَّ وَجَلَّ ‏{‏فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ * يَغْشَى النَّاسَ هَذَا عَذَابٌ أَلِيمٌ‏}‏ قَالَ فَدَعَوْا ‏{‏رَبَّنَا اكْشِفْ عَنَّا الْعَذَابَ إِنَّا مُؤْمِنُونَ * أَنَّى لَهُمُ الذِّكْرَى وَقَدْ جَاءَهُمْ رَسُولٌ مُبِينٌ * ثُمَّ تَوَلَّوْا عَنْهُ وَقَالُوا مُعَلَّمٌ مَجْنُونٌ * إِنَّا كَاشِفُو الْعَذَابِ قَلِيلاً إِنَّكُمْ عَائِدُونَ‏}‏ أَفَيُكْشَفُ الْعَذَابُ يَوْمَ الْقِيَامَةِ قَالَ فَكُشِفَ ثُمَّ عَادُوا فِي كُفْرِهِمْ، فَأَخَذَهُمُ اللَّهُ يَوْمَ بَدْرٍ قَالَ اللَّهُ تَعَالَى ‏{‏يَوْمَ نَبْطِشُ الْبَطْشَةَ الْكُبْرَى إِنَّا مُنْتَقِمُونَ‏}‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4821","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4821","x":"Narrated `Abdullah:\n\nIt (i.e., the imagined smoke) was because, when the Quraish refused to obey the Prophet, he asked Allah to afflict them with years of famine similar to those of (Prophet) Joseph. So they were stricken with famine and fatigue, so much so that they ate even bones. A man would look towards the sky and imagine seeing something like smoke between him and the sky because of extreme fatigue. So Allah revealed:-- 'Then watch you for the Day that the sky will bring forth a kind of smoke plainly visible, covering the people; this is a painfull of torment.' (44.10-11) Then someone (Abu Sufyan) came to Allah's Messenger (ﷺ) and said, \"O Allah's Messenger (ﷺ)! Invoke Allah to send rain for the tribes of Mudar for they are on the verge of destruction.\" On that the Prophet (ﷺ) said (astonishingly) \"Shall I invoke Allah) for the tribes of Mudar? Verily, you are a brave man!\" But the Prophet prayed for rain and it rained for them. Then the Verse was revealed. 'But truly you will return (to disbelief).' (44.15) (When the famine was over and) they restored prosperity and welfare, they reverted to their ways (of heathenism) whereupon Allah revealed: 'On the Day when We shall seize you with a Mighty Grasp. We will indeed (then) exact retribution.' (44.16) The narrator said, \"That was the day of the Battle of Badr.\"","ar":"حَدَّثَنَا يَحْيَى، حَدَّثَنَا أَبُو مُعَاوِيَةَ، عَنِ الأَعْمَشِ، عَنْ مُسْلِمٍ، عَنْ مَسْرُوقٍ، قَالَ قَالَ عَبْدُ اللَّهِ إِنَّمَا كَانَ هَذَا لأَنَّ قُرَيْشًا لَمَّا اسْتَعْصَوْا عَلَى النَّبِيِّ صلى الله عليه وسلم دَعَا عَلَيْهِمْ بِسِنِينَ كَسِنِي يُوسُفَ، فَأَصَابَهُمْ قَحْطٌ وَجَهْدٌ حَتَّى أَكَلُوا الْعِظَامَ، فَجَعَلَ الرَّجُلُ يَنْظُرُ إِلَى السَّمَاءِ فَيَرَى مَا بَيْنَهُ وَبَيْنَهَا كَهَيْئَةِ الدُّخَانِ مِنَ الْجَهْدِ، فَأَنْزَلَ اللَّهُ تَعَالَى ‏{‏فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ * يَغْشَى النَّاسَ هَذَا عَذَابٌ أَلِيمٌ‏}‏ قَالَ فَأُتِيَ رَسُولُ اللَّهِ صلى الله عليه وسلم فَقِيلَ يَا رَسُولَ اللَّهِ اسْتَسْقِ اللَّهَ لِمُضَرَ، فَإِنَّهَا قَدْ هَلَكَتْ‏.‏ قَالَ ‏\"‏ لِمُضَرَ إِنَّكَ لَجَرِيءٌ ‏\"‏‏.‏ فَاسْتَسْقَى فَسُقُوا‏.‏ فَنَزَلَتْ ‏{‏إِنَّكُمْ عَائِدُونَ‏}‏ فَلَمَّا أَصَابَتْهُمُ الرَّفَاهِيَةُ عَادُوا إِلَى حَالِهِمْ حِينَ أَصَابَتْهُمُ الرَّفَاهِيَةُ‏.‏ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏{‏يَوْمَ نَبْطِشُ الْبَطْشَةَ الْكُبْرَى إِنَّا مُنْتَقِمُونَ‏}‏ قَالَ يَعْنِي يَوْمَ بَدْرٍ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4823","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4823","x":"Narrated Masruq:\n\nI came upon `Abdullah and he said, \"When Allah's Messenger (ﷺ) invited Quraish (to Islam), they disbelieved him and stood against him. So he (the Prophet) said, \"O Allah! Help me against them by afflicting them with seven years of famine similar to the seven years of Joseph.' So they were stricken with a year of drought that destroyed everything, and they started eating dead animals, and if one of them got up he would see something like smoke between him and the sky from the severe fatigue and hunger.\" `Abdullah then recited:-- 'Then watch you for the Day that the sky will bring forth a kind of smoke plainly visible, covering the people. This is a painful torment... (till he reached)........ We shall indeed remove the punishment for a while, but truly you will revert (to heathenism): (44.10-15) `Abdullah added: \"Will the punishment be removed from them on the Day of Resurrection?\" He added,\" The severe grasp\" was the Day of the Battle of Badr.\"","ar":"حَدَّثَنَا سُلَيْمَانُ بْنُ حَرْبٍ، حَدَّثَنَا جَرِيرُ بْنُ حَازِمٍ، عَنِ الأَعْمَشِ، عَنْ أَبِي الضُّحَى، عَنْ مَسْرُوقٍ، قَالَ دَخَلْتُ عَلَى عَبْدِ اللَّهِ ثُمَّ قَالَ إِنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم لَمَّا دَعَا قُرَيْشًا كَذَّبُوهُ وَاسْتَعْصَوْا عَلَيْهِ فَقَالَ ‏\"‏ اللَّهُمَّ أَعِنِّي عَلَيْهِمْ بِسَبْعٍ كَسَبْعِ يُوسُفَ ‏\"‏‏.‏ فَأَصَابَتْهُمْ سَنَةٌ حَصَّتْ ـ يَعْنِي ـ كُلَّ شَىْءٍ حَتَّى كَانُوا يَأْكُلُونَ الْمَيْتَةَ فَكَانَ يَقُومُ أَحَدُهُمْ فَكَانَ يَرَى بَيْنَهُ وَبَيْنَ السَّمَاءِ مِثْلَ الدُّخَانِ مِنَ الْجَهْدِ وَالْجُوعِ ثُمَّ قَرَأَ ‏{‏فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ * يَغْشَى النَّاسَ هَذَا عَذَابٌ أَلِيمٌ‏}‏ حَتَّى بَلَغَ ‏{‏إِنَّا كَاشِفُو الْعَذَابِ قَلِيلاً إِنَّكُمْ عَائِدُونَ‏}‏ قَالَ عَبْدُ اللَّهِ أَفَيُكْشَفُ عَنْهُمُ الْعَذَابُ يَوْمَ الْقِيَامَةِ قَالَ وَالْبَطْشَةُ الْكُبْرَى يَوْمَ بَدْرٍ‏.‏","v":[]}],"12":[{"c":"Sahih Bukhari","r":"Hadith 1007","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-1007","x":"Narrated Masruq:\n\nWe were with `Abdullah and he said, \"When the Prophet (ﷺ) saw the refusal of the people to accept Islam he said, \"O Allah! Send (famine) years on them for (seven years) like the seven years (of famine during the time) of (Prophet) Joseph.\" So famine overtook them for one year and destroyed every kind of life to such an extent that the people started eating hides, carcasses and rotten dead animals. Whenever one of them looked towards the sky, he would (imagine himself to) see smoke because of hunger. So Abu Sufyan went to the Prophet (ﷺ) and said, \"O Muhammad! You order people to obey Allah and to keep good relations with kith and kin. No doubt the people of your tribe are dying, so please pray to Allah for them.\" So Allah revealed: \"Then watch you For the day that The sky will bring forth a kind Of smoke Plainly visible... Verily! You will return (to disbelief) On the day when We shall seize You with a mighty grasp. (44.10-16) Ibn Mas`ud added, \"Al-Batsha (i.e. grasp) happened in the battle of Badr and no doubt smoke, Al-Batsha, Al-Lizam, and the verse of Surat Ar-Rum have all passed.","ar":"حَدَّثَنَا عُثْمَانُ بْنُ أَبِي شَيْبَةَ، قَالَ حَدَّثَنَا جَرِيرٌ، عَنْ مَنْصُورٍ، عَنْ أَبِي الضُّحَى، عَنْ مَسْرُوقٍ، قَالَ كُنَّا عِنْدَ عَبْدِ اللَّهِ فَقَالَ إِنَّ النَّبِيَّ صلى الله عليه وسلم لَمَّا رَأَى مِنَ النَّاسِ إِدْبَارًا قَالَ ‏\"‏ اللَّهُمَّ سَبْعٌ كَسَبْعِ يُوسُفَ ‏\"‏‏.‏ فَأَخَذَتْهُمْ سَنَةٌ حَصَّتْ كُلَّ شَىْءٍ حَتَّى أَكَلُوا الْجُلُودَ وَالْمَيْتَةَ وَالْجِيَفَ، وَيَنْظُرَ أَحَدُهُمْ إِلَى السَّمَاءِ فَيَرَى الدُّخَانَ مِنَ الْجُوعِ، فَأَتَاهُ أَبُو سُفْيَانَ فَقَالَ يَا مُحَمَّدُ إِنَّكَ تَأْمُرُ بِطَاعَةِ اللَّهِ وَبِصِلَةِ الرَّحِمِ وَإِنَّ قَوْمَكَ قَدْ هَلَكُوا، فَادْعُ اللَّهَ لَهُمْ قَالَ اللَّهُ تَعَالَى ‏{‏فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ‏}‏ إِلَى قَوْلِهِ ‏{‏عَائِدُونَ * يَوْمَ نَبْطِشُ الْبَطْشَةَ الْكُبْرَى‏}‏ فَالْبَطْشَةُ يَوْمَ بَدْرٍ، وَقَدْ مَضَتِ الدُّخَانُ وَالْبَطْشَةُ وَاللِّزَامُ وَآيَةُ الرُّومِ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 1020","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-1020","x":"Narrated Masruq:\n\nOne day I went to Ibn Mas`ud who said, \"When Quraish delayed in embracing Islam, the Prophet (ﷺ) I invoked Allah to curse them, so they were afflicted with a (famine) year because of which many of them died and they ate the carcasses and Abu Sufyan came to the Prophet (ﷺ) and said, 'O Muhammad! You came to order people to keep good relation with kith and kin and your nation is being destroyed, so invoke Allah I ? So the Prophet (ﷺ) I recited the Holy verses of Sirat-Ad-Dukhan: 'Then watch you For the day that The sky will Bring forth a kind Of smoke Plainly visible.' (44.10) When the famine was taken off, the people renegade once again as nonbelievers. The statement of Allah, (in Sura \"Ad- Dukhan\"-44) refers to that: 'On the day when We shall seize You with a mighty grasp.' (44.16) And that was what happened on the day of the battle of Badr.\" Asbath added on the authority of Mansur, \"Allah's Messenger (ﷺ) prayed for them and it rained heavily for seven days. So the people complained of the excessive rain. The Prophet (ﷺ) said, 'O Allah! (Let it rain) around us and not on us.' So the clouds dispersed over his head and it rained over the surroundings.\"","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ كَثِيرٍ، عَنْ سُفْيَانَ، حَدَّثَنَا مَنْصُورٌ، وَالأَعْمَشُ، عَنْ أَبِي الضُّحَى، عَنْ مَسْرُوقٍ، قَالَ أَتَيْتُ ابْنَ مَسْعُودٍ فَقَالَ إِنَّ قُرَيْشًا أَبْطَئُوا عَنِ الإِسْلاَمِ،، فَدَعَا عَلَيْهِمُ النَّبِيُّ صلى الله عليه وسلم فَأَخَذَتْهُمْ سَنَةٌ حَتَّى هَلَكُوا فِيهَا وَأَكَلُوا الْمَيْتَةَ وَالْعِظَامَ، فَجَاءَهُ أَبُو سُفْيَانَ فَقَالَ يَا مُحَمَّدُ، جِئْتَ تَأْمُرُ بِصِلَةِ الرَّحِمِ، وَإِنَّ قَوْمَكَ هَلَكُوا، فَادْعُ اللَّهَ‏.‏ فَقَرَأَ ‏{‏فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ‏}‏ ثُمَّ عَادُوا إِلَى كُفْرِهِمْ فَذَلِكَ قَوْلُهُ تَعَالَى ‏{‏يَوْمَ نَبْطِشُ الْبَطْشَةَ الْكُبْرَى‏}‏ يَوْمَ بَدْرٍ‏.‏ قَالَ وَزَادَ أَسْبَاطٌ عَنْ مَنْصُورٍ فَدَعَا رَسُولُ اللَّهِ صلى الله عليه وسلم، فَسُقُوا الْغَيْثَ، فَأَطْبَقَتْ عَلَيْهِمْ سَبْعًا، وَشَكَا النَّاسُ كَثْرَةَ الْمَطَرِ فَقَالَ ‏\"‏ اللَّهُمَّ حَوَالَيْنَا وَلاَ عَلَيْنَا ‏\"‏‏.‏ فَانْحَدَرَتِ السَّحَابَةُ عَنْ رَأْسِهِ، فَسُقُوا النَّاسُ حَوْلَهُمْ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4774","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4774","x":"Narrated Masruq:\n\nWhile a man was delivering a speech in the tribe of Kinda, he said, \"Smoke will prevail on the Day of Resurrection and will deprive the hypocrites their faculties of hearing and seeing. The believers will be afflicted with something like cold only thereof.\" That news scared us, so I went to (Abdullah) Ibn Mas`ud while he was reclining (and told him the story) whereupon he became angry, sat up and said, \"He who knows a thing can say, it, but if he does not know, he should say, 'Allah knows best,' for it is an aspect of knowledge to say, 'I do not know,' if you do not know a certain thing. Allah said to His prophet. 'Say (O Muhammad): No wage do I ask of you for this (Qur'an), nor I am one of the pretenders (a person who pretends things which do not exist.)' (38.86) The Qur'aish delayed in embracing Islam for a period, so the Prophet (ﷺ) invoked evil on them, saying, 'O Allah! Help me against them by sending seven years of (famine) like those of Joseph.' So they were afflicted with such a severe year of famine that they were destroyed therein and ate dead animals and bones. They started seeing something like smoke between the sky and the earth (because of severe hunger). Abu Sufyan then came (to the Prophet) and said, \"O Muhammad! You came to order us for to keep good relations with Kith and kin, and your kinsmen have now perished, so please invoke Allah (to relieve them).' Then Ibn Mas`ud recited:-- 'Then watch you for the day that the sky will bring forth a kind of smoke plainly visible....but truly you will return! (to disbelief) (44.10-15) Ibn Mas`ud added, Then the punishment was stopped, but truly, they reverted to heathenism (their old way). So Allah (threatened them thus): 'On the day when we shall seize you with a mighty grasp.' (44.16) And that was the day of the Battle of Badr. Allah's saying- \"Lizama\" (the punishment) refers to the day of Badr Allah's Statement: Alif-Lam-Mim, the Romans have been defeated, and they, after their defeat, will be victorious,' (30.1- 3) (This verse): Indicates that the defeat of Byzantine has already passed.","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ كَثِيرٍ، حَدَّثَنَا سُفْيَانُ، حَدَّثَنَا مَنْصُورٌ، وَالأَعْمَشُ، عَنْ أَبِي الضُّحَى، عَنْ مَسْرُوقٍ، قَالَ بَيْنَمَا رَجُلٌ يُحَدِّثُ فِي كِنْدَةَ فَقَالَ يَجِيءُ دُخَانٌ يَوْمَ الْقِيَامَةِ فَيَأْخُذُ بِأَسْمَاعِ الْمُنَافِقِينَ وَأَبْصَارِهِمْ، يَأْخُذُ الْمُؤْمِنَ كَهَيْئَةِ الزُّكَامِ‏.‏ فَفَزِعْنَا، فَأَتَيْتُ ابْنَ مَسْعُودٍ، وَكَانَ مُتَّكِئًا، فَغَضِبَ فَجَلَسَ فَقَالَ مَنْ عَلِمَ فَلْيَقُلْ، وَمَنْ لَمْ يَعْلَمْ فَلْيَقُلِ اللَّهُ أَعْلَمُ‏.‏ فَإِنَّ مِنَ الْعِلْمِ أَنْ يَقُولَ لِمَا لاَ يَعْلَمُ لاَ أَعْلَمُ‏.‏ فَإِنَّ اللَّهَ قَالَ لِنَبِيِّهِ صلى الله عليه وسلم ‏{‏قُلْ مَا أَسْأَلُكُمْ عَلَيْهِ مِنْ أَجْرٍ وَمَا أَنَا مِنَ الْمُتَكَلِّفِينَ‏}‏ وَإِنَّ قُرَيْشًا أَبْطَئُوا عَنِ الإِسْلاَمِ فَدَعَا عَلَيْهِمِ النَّبِيُّ صلى الله عليه وسلم فَقَالَ ‏\"‏ اللَّهُمَّ أَعِنِّي عَلَيْهِمْ بِسَبْعٍ كَسَبْعِ يُوسُفَ، فَأَخَذَتْهُمْ سَنَةٌ حَتَّى هَلَكُوا فِيهَا، وَأَكَلُوا الْمَيْتَةَ وَالْعِظَامَ وَيَرَى الرَّجُلُ مَا بَيْنَ السَّمَاءِ وَالأَرْضِ كَهَيْئَةِ الدُّخَانِ ‏\"‏، فَجَاءَهُ أَبُو سُفْيَانَ فَقَالَ يَا مُحَمَّدُ جِئْتَ تَأْمُرُنَا بِصِلَةِ الرَّحِمِ، وَإِنَّ قَوْمَكَ قَدْ هَلَكُوا فَادْعُ اللَّهَ، فَقَرَأَ ‏{‏فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ‏}‏ إِلَى قَوْلِهِ ‏{‏عَائِدُونَ‏}‏ أَفَيُكْشَفُ عَنْهُمْ عَذَابُ الآخِرَةِ إِذَا جَاءَ ثُمَّ عَادُوا إِلَى كُفْرِهِمْ فَذَلِكَ قَوْلُهُ تَعَالَى ‏{‏يَوْمَ نَبْطِشُ الْبَطْشَةَ الْكُبْرَى‏}‏ يَوْمَ بَدْرٍ وَلِزَامًا يَوْمَ بَدْرٍ ‏{‏الم * غُلِبَتِ الرُّومُ‏}‏ إِلَى ‏{‏سَيَغْلِبُونَ‏}‏ وَالرُّومُ قَدْ مَضَى‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4809","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4809","x":"Narrated Masruq:\n\nWe came upon `Abdullah bin Mas`ud and he said \"O people! If somebody knows something, he can say it, but if he does not know it, he should say, \"Allah knows better,' for it is a sign of having knowledge to say about something which one does not know, 'Allah knows better.' Allah said to His Prophet: 'Say (O Muhammad ! ) No wage do I ask of You for this (Qur'an) nor am I one of the pretenders (a person who pretends things which do not exist).' (38.86) Now I will tell you about Ad- Dukhan (the smoke), Allah's Messenger (ﷺ) invited the Quraish to embrace Islam, but they delayed their response. So he said, \"O Allah! Help me against them by sending on them seven years of famine similar to the seven years of famine of Joseph.\" So the famine year overtook them and everything was destroyed till they ate dead animals and skins. People started imagining to see smoke between them and the sky because of severe hunger. Allah said: 'Then watch you for the Day that the sky will bring forth a kind of smoke plainly visible, covering the people... This is painful torment.' (44.10-11) (So they invoked Allah) \"Our Lord! Remove the punishment from us really we are believers.\" How can there be an (effectual) reminder for them when an Apostle, explaining things clearly, has already come to them? Then they had turned away from him and said: 'One taught (by a human being), a madman?' 'We shall indeed remove punishment for a while, but truly, you will revert (to disbelief).' (44.12-15) Will the punishment be removed on the Day of Resurrection?\" `Abdullah added, \"The punishment was removed from them for a while but they reverted to disbelief, so Allah destroyed them on the Day of Badr. Allah said: 'The day We shall seize you with a mighty grasp. We will indeed (then) exact retribution.\" (44.16)","ar":"حَدَّثَنَا قُتَيْبَةُ، حَدَّثَنَا جَرِيرٌ، عَنِ الأَعْمَشِ، عَنْ أَبِي الضُّحَى، عَنْ مَسْرُوقٍ، قَالَ دَخَلْنَا عَلَى عَبْدِ اللَّهِ بْنِ مَسْعُودٍ، قَالَ يَا أَيُّهَا النَّاسُ مَنْ عَلِمَ شَيْئًا فَلْيَقُلْ بِهِ، وَمَنْ لَمْ يَعْلَمْ فَلْيَقُلِ اللَّهُ أَعْلَمُ، فَإِنَّ مِنَ الْعِلْمِ أَنْ يَقُولَ لِمَا لاَ يَعْلَمُ اللَّهُ أَعْلَمُ، قَالَ اللَّهُ عَزَّ وَجَلَّ لِنَبِيِّهِ صلى الله عليه وسلم ‏{‏قُلْ مَا أَسْأَلُكُمْ عَلَيْهِ مِنْ أَجْرٍ وَمَا أَنَا مِنَ الْمُتَكَلِّفِينَ‏}‏ وَسَأُحَدِّثُكُمْ عَنِ الدُّخَانِ إِنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم دَعَا قُرَيْشًا إِلَى الإِسْلاَمِ فَأَبْطَئُوا عَلَيْهِ فَقَالَ ‏\"‏ اللَّهُمَّ أَعِنِّي عَلَيْهِمْ بِسَبْعٍ كَسَبْعِ يُوسُفَ ‏\"‏، فَأَخَذَتْهُمْ سَنَةٌ فَحَصَّتْ كُلَّ شَىْءٍ حَتَّى أَكَلُوا الْمَيْتَةَ وَالْجُلُودَ حَتَّى جَعَلَ الرَّجُلُ يَرَى بَيْنَهُ وَبَيْنَ السَّمَاءِ دُخَانًا مِنَ الْجُوعِ، قَالَ اللَّهُ عَزَّ وَجَلَّ ‏{‏فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ * يَغْشَى النَّاسَ هَذَا عَذَابٌ أَلِيمٌ‏}‏ قَالَ فَدَعَوْا ‏{‏رَبَّنَا اكْشِفْ عَنَّا الْعَذَابَ إِنَّا مُؤْمِنُونَ * أَنَّى لَهُمُ الذِّكْرَى وَقَدْ جَاءَهُمْ رَسُولٌ مُبِينٌ * ثُمَّ تَوَلَّوْا عَنْهُ وَقَالُوا مُعَلَّمٌ مَجْنُونٌ * إِنَّا كَاشِفُو الْعَذَابِ قَلِيلاً إِنَّكُمْ عَائِدُونَ‏}‏ أَفَيُكْشَفُ الْعَذَابُ يَوْمَ الْقِيَامَةِ قَالَ فَكُشِفَ ثُمَّ عَادُوا فِي كُفْرِهِمْ، فَأَخَذَهُمُ اللَّهُ يَوْمَ بَدْرٍ قَالَ اللَّهُ تَعَالَى ‏{‏يَوْمَ نَبْطِشُ الْبَطْشَةَ الْكُبْرَى إِنَّا مُنْتَقِمُونَ‏}‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4822","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4822","x":"Narrated `Abdullah:\n\nIt is a sign of having knowledge that, when you do not know something, you say: 'Allah knows better.' Allah said to his Prophet: 'Say: No wage do I ask of you for this (Qur'an), nor am I one of the pretenders (a person who pretends things which do not exist)' (38.86) When the Quraish troubled and stood against the Prophet (ﷺ) he said, \"O Allah! Help me against them by afflicting them with seven years of famine like the seven years of Joseph.\" So they were stricken with a year of famine during which they ate bones and dead animals because of too much suffering, and one of them would see something like smoke between him and the sky because of hunger. Then they said: Our Lord! Remove the torment from us, really we are believers. (44.12) And then it was said to the Prophet (by Allah), \"If we remove it from them. they will revert to their ways (of heathenism).\" So the Prophet (ﷺ) invoked his Lord, who removed the punishment from them, but later they reverted (to heathenism), whereupon Allah punished them on the day of the Battle of Badr, and that is what Allah's Statement indicates: 'Then watch for the day that the sky will bring forth a kind of smoke plainly visible...we will indeed (then) exact retribution.' (44.10).","ar":"حَدَّثَنَا يَحْيَى، حَدَّثَنَا وَكِيعٌ، عَنِ الأَعْمَشِ، عَنْ أَبِي الضُّحَى، عَنْ مَسْرُوقٍ، قَالَ دَخَلْتُ عَلَى عَبْدِ اللَّهِ فَقَالَ إِنَّ مِنَ الْعِلْمِ أَنْ تَقُولَ لِمَا لاَ تَعْلَمُ اللَّهُ أَعْلَمُ، إِنَّ اللَّهَ قَالَ لِنَبِيِّهِ صلى الله عليه وسلم ‏{‏قُلْ مَا أَسْأَلُكُمْ عَلَيْهِ مِنْ أَجْرٍ وَمَا أَنَا مِنَ الْمُتَكَلِّفِينَ‏}‏ إِنَّ قُرَيْشًا لَمَّا غَلَبُوا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَاسْتَعْصَوْا عَلَيْهِ قَالَ اللَّهُمَّ أَعِنِّي عَلَيْهِمْ بِسَبْعٍ كَسَبْعِ يُوسُفَ فَأَخَذَتْهُمْ سَنَةٌ أَكَلُوا فِيهَا الْعِظَامَ وَالْمَيْتَةَ مِنْ الْجَهْدِ حَتَّى جَعَلَ أَحَدُهُمْ يَرَى مَا بَيْنَهُ وَبَيْنَ السَّمَاءِ كَهَيْئَةِ الدُّخَانِ مِنْ الْجُوعِ قَالُوا ￼ رَبَّنَا اكْشِفْ عَنَّا الْعَذَابَ إِنَّا مُؤْمِنُونَ ￼ فَقِيلَ لَهُ إِنْ كَشَفْنَا عَنْهُمْ عَادُوا فَدَعَا رَبَّهُ فَكَشَفَ عَنْهُمْ فَعَادُوا فَانْتَقَمَ اللَّهُ مِنْهُمْ يَوْمَ بَدْرٍ فَذَلِكَ قَوْلُهُ تَعَالَى ￼ فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ إِلَى قَوْلِهِ جَلَّ ذِكْرُهُ إِنَّا مُنْتَقِمُونَ.","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4823","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4823","x":"Narrated Masruq:\n\nI came upon `Abdullah and he said, \"When Allah's Messenger (ﷺ) invited Quraish (to Islam), they disbelieved him and stood against him. So he (the Prophet) said, \"O Allah! Help me against them by afflicting them with seven years of famine similar to the seven years of Joseph.' So they were stricken with a year of drought that destroyed everything, and they started eating dead animals, and if one of them got up he would see something like smoke between him and the sky from the severe fatigue and hunger.\" `Abdullah then recited:-- 'Then watch you for the Day that the sky will bring forth a kind of smoke plainly visible, covering the people. This is a painful torment... (till he reached)........ We shall indeed remove the punishment for a while, but truly you will revert (to heathenism): (44.10-15) `Abdullah added: \"Will the punishment be removed from them on the Day of Resurrection?\" He added,\" The severe grasp\" was the Day of the Battle of Badr.\"","ar":"حَدَّثَنَا سُلَيْمَانُ بْنُ حَرْبٍ، حَدَّثَنَا جَرِيرُ بْنُ حَازِمٍ، عَنِ الأَعْمَشِ، عَنْ أَبِي الضُّحَى، عَنْ مَسْرُوقٍ، قَالَ دَخَلْتُ عَلَى عَبْدِ اللَّهِ ثُمَّ قَالَ إِنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم لَمَّا دَعَا قُرَيْشًا كَذَّبُوهُ وَاسْتَعْصَوْا عَلَيْهِ فَقَالَ ‏\"‏ اللَّهُمَّ أَعِنِّي عَلَيْهِمْ بِسَبْعٍ كَسَبْعِ يُوسُفَ ‏\"‏‏.‏ فَأَصَابَتْهُمْ سَنَةٌ حَصَّتْ ـ يَعْنِي ـ كُلَّ شَىْءٍ حَتَّى كَانُوا يَأْكُلُونَ الْمَيْتَةَ فَكَانَ يَقُومُ أَحَدُهُمْ فَكَانَ يَرَى بَيْنَهُ وَبَيْنَ السَّمَاءِ مِثْلَ الدُّخَانِ مِنَ الْجَهْدِ وَالْجُوعِ ثُمَّ قَرَأَ ‏{‏فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ * يَغْشَى النَّاسَ هَذَا عَذَابٌ أَلِيمٌ‏}‏ حَتَّى بَلَغَ ‏{‏إِنَّا كَاشِفُو الْعَذَابِ قَلِيلاً إِنَّكُمْ عَائِدُونَ‏}‏ قَالَ عَبْدُ اللَّهِ أَفَيُكْشَفُ عَنْهُمُ الْعَذَابُ يَوْمَ الْقِيَامَةِ قَالَ وَالْبَطْشَةُ الْكُبْرَى يَوْمَ بَدْرٍ‏.‏","v":[]},{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3254","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3254","x":"Narrated Masruq:\n\n\"A man came to 'Abdullah and said: 'A story teller has said that a smoke will appear from the earth, taking the hearing of disbelievers and manifesting as a cold for the believers.'\" He became angry, and since he was reclining, he sat up then said: 'When one of you is asked about something he knows, then let him speak accordingly' - Mansur (one of the narrators) narrated it as: \"Then let him inform of it\" - \"And when asked about what he does not know, then let him say: \"Allah knows best.\" For indeed, it is part of a man's knowledge, that when he is asked about something he does not know, he says: \"Allah knows best.\" For verily Allah, Most High said to His Prophet: Say: \"No wage do I ask of you for this, nor am I one of the pretenders (38:86).\" When the Messenger of Allah (ﷺ) saw that the Quraish were behaving stubbornly with him, he said: \"O Allah! Assist me against them with seven (years of famine) like the seven of Yusuf.\" So He punished them with drought making everything barren, until they ate skins and carcasses\" - one of them said: \"bones.\" He said: 'And it appeared that smoke was coming out of the earth. So Abu Sufyan came to him and said: \"Verily your people are being destroyed, so supplicate to Allah for them.\" He said: \"So this is about His saying: 'The Day when the sky will bring forth a visible smoke, covering the people, this is a painful torment (44:10 & 11).'\" Mansur narrated it as: \"So this is about His saying: Our Lord! Remove the torment from us, really we shall become believers (44:12).\" - \"So shall the punishment be removed from them in the Hereafter? Al-Batshah (humiliated defeat in Badr), Al-Lizam (disbeliever captives from Badr), the smoke,\" - one of them said: \"The moon\" the other said: \"The Romans have all passed.\"","ar":"حَدَّثَنَا مَحْمُودُ بْنُ غَيْلاَنَ، حَدَّثَنَا عَبْدُ الْمَلِكِ بْنُ إِبْرَاهِيمَ الْجُدِّيُّ، حَدَّثَنَا شُعْبَةُ، عَنِ الأَعْمَشِ، وَمَنْصُورٍ، سَمِعَا أَبَا الضُّحَى، يُحَدِّثُ عَنْ مَسْرُوقٍ، قَالَ جَاءَ رَجُلٌ إِلَى عَبْدِ اللَّهِ فَقَالَ إِنَّ قَاصًّا يَقُصُّ يَقُولُ إِنَّهُ يَخْرُجُ مِنَ الأَرْضِ الدُّخَانُ فَيَأْخُذُ بِمَسَامِعِ الْكُفَّارِ وَيَأْخُذُ الْمُؤْمِنَ كَهَيْئَةِ الزُّكَامِ قَالَ فَغَضِبَ وَكَانَ مُتَّكِئًا فَجَلَسَ ثُمَّ قَالَ إِذَا سُئِلَ أَحَدُكُمْ عَمَّا يَعْلَمُ فَلْيَقُلْ بِهِ قَالَ مَنْصُورٌ فَلْيُخْبِرْ بِهِ وَإِذَا سُئِلَ عَمَّا لاَ يَعْلَمُ فَلْيَقُلِ اللَّهُ أَعْلَمُ فَإِنَّ مِنْ عِلْمِ الرَّجُلِ إِذَا سُئِلَ عَمَّا لاَ يَعْلَمُ أَنْ يَقُولَ اللَّهُ أَعْلَمُ فَإِنَّ اللَّهَ تَعَالَى قَالَ لِنَبِيِّهِ ‏:‏ ‏(‏قلْ مَا أَسْأَلُكُمْ عَلَيْهِ مِنْ أَجْرٍ وَمَا أَنَا مِنَ الْمُتَكَلِّفِينَ ‏)‏ ‏\"‏ ‏.‏ إِنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم لَمَّا رَأَى قُرَيْشًا اسْتَعْصَوْا عَلَيْهِ قَالَ ‏\"‏ اللَّهُمَّ أَعِنِّي عَلَيْهِمْ بِسَبْعٍ كَسَبْعِ يُوسُفَ ‏\"‏ ‏.‏ فَأَخَذَتْهُمْ سَنَةٌ فَأَحْصَتْ كُلَّ شَيْءٍ حَتَّى أَكَلُوا الْجُلُودَ وَالْمَيْتَةَ وَقَالَ أَحَدُهُمَا الْعِظَامَ قَالَ وَجَعَلَ يَخْرُجُ مِنَ الأَرْضِ كَهَيْئَةِ الدُّخَانِ قَالَ فَأَتَاهُ أَبُو سُفْيَانَ قَالَ إِنَّ قَوْمَكَ قَدْ هَلَكُوا فَادْعُ اللَّهَ لَهُمْ ‏.‏ قَالَ فَهَذَا لِقَوْلِهِ ‏:‏ ‏(‏ يوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ * يَغْشَى النَّاسَ هَذَا عَذَابٌ أَلِيمٌ ‏)‏ ‏.‏ قَالَ مَنْصُورٌ هَذَا لِقَوْلِهِ ‏(‏ رَبَّنَا اكْشِفْ عَنَّا الْعَذَابَ إِنَّا مُؤْمِنُونَ ‏)‏ فَهَلْ يُكْشَفُ عَذَابُ الآخِرَةِ قَالَ مَضَى الْبَطْشَةُ وَاللِّزَامُ الدُّخَانُ وَقَالَ أَحَدُهُمَا الْقَمَرُ وَقَالَ الآخَرُ الرُّومُ ‏.‏ قَالَ أَبُو عِيسَى وَاللِّزَامُ يَعْنِي يَوْمَ بَدْرٍ ‏.‏ قَالَ وَهَذَا حَدِيثٌ حَسَنٌ صَحِيحٌ ‏.‏","v":[]}],"13":[{"c":"Sahih Bukhari","r":"Hadith 1007","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-1007","x":"Narrated Masruq:\n\nWe were with `Abdullah and he said, \"When the Prophet (ﷺ) saw the refusal of the people to accept Islam he said, \"O Allah! Send (famine) years on them for (seven years) like the seven years (of famine during the time) of (Prophet) Joseph.\" So famine overtook them for one year and destroyed every kind of life to such an extent that the people started eating hides, carcasses and rotten dead animals. Whenever one of them looked towards the sky, he would (imagine himself to) see smoke because of hunger. So Abu Sufyan went to the Prophet (ﷺ) and said, \"O Muhammad! You order people to obey Allah and to keep good relations with kith and kin. No doubt the people of your tribe are dying, so please pray to Allah for them.\" So Allah revealed: \"Then watch you For the day that The sky will bring forth a kind Of smoke Plainly visible... Verily! You will return (to disbelief) On the day when We shall seize You with a mighty grasp. (44.10-16) Ibn Mas`ud added, \"Al-Batsha (i.e. grasp) happened in the battle of Badr and no doubt smoke, Al-Batsha, Al-Lizam, and the verse of Surat Ar-Rum have all passed.","ar":"حَدَّثَنَا عُثْمَانُ بْنُ أَبِي شَيْبَةَ، قَالَ حَدَّثَنَا جَرِيرٌ، عَنْ مَنْصُورٍ، عَنْ أَبِي الضُّحَى، عَنْ مَسْرُوقٍ، قَالَ كُنَّا عِنْدَ عَبْدِ اللَّهِ فَقَالَ إِنَّ النَّبِيَّ صلى الله عليه وسلم لَمَّا رَأَى مِنَ النَّاسِ إِدْبَارًا قَالَ ‏\"‏ اللَّهُمَّ سَبْعٌ كَسَبْعِ يُوسُفَ ‏\"‏‏.‏ فَأَخَذَتْهُمْ سَنَةٌ حَصَّتْ كُلَّ شَىْءٍ حَتَّى أَكَلُوا الْجُلُودَ وَالْمَيْتَةَ وَالْجِيَفَ، وَيَنْظُرَ أَحَدُهُمْ إِلَى السَّمَاءِ فَيَرَى الدُّخَانَ مِنَ الْجُوعِ، فَأَتَاهُ أَبُو سُفْيَانَ فَقَالَ يَا مُحَمَّدُ إِنَّكَ تَأْمُرُ بِطَاعَةِ اللَّهِ وَبِصِلَةِ الرَّحِمِ وَإِنَّ قَوْمَكَ قَدْ هَلَكُوا، فَادْعُ اللَّهَ لَهُمْ قَالَ اللَّهُ تَعَالَى ‏{‏فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ‏}‏ إِلَى قَوْلِهِ ‏{‏عَائِدُونَ * يَوْمَ نَبْطِشُ الْبَطْشَةَ الْكُبْرَى‏}‏ فَالْبَطْشَةُ يَوْمَ بَدْرٍ، وَقَدْ مَضَتِ الدُّخَانُ وَالْبَطْشَةُ وَاللِّزَامُ وَآيَةُ الرُّومِ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 1020","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-1020","x":"Narrated Masruq:\n\nOne day I went to Ibn Mas`ud who said, \"When Quraish delayed in embracing Islam, the Prophet (ﷺ) I invoked Allah to curse them, so they were afflicted with a (famine) year because of which many of them died and they ate the carcasses and Abu Sufyan came to the Prophet (ﷺ) and said, 'O Muhammad! You came to order people to keep good relation with kith and kin and your nation is being destroyed, so invoke Allah I ? So the Prophet (ﷺ) I recited the Holy verses of Sirat-Ad-Dukhan: 'Then watch you For the day that The sky will Bring forth a kind Of smoke Plainly visible.' (44.10) When the famine was taken off, the people renegade once again as nonbelievers. The statement of Allah, (in Sura \"Ad- Dukhan\"-44) refers to that: 'On the day when We shall seize You with a mighty grasp.' (44.16) And that was what happened on the day of the battle of Badr.\" Asbath added on the authority of Mansur, \"Allah's Messenger (ﷺ) prayed for them and it rained heavily for seven days. So the people complained of the excessive rain. The Prophet (ﷺ) said, 'O Allah! (Let it rain) around us and not on us.' So the clouds dispersed over his head and it rained over the surroundings.\"","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ كَثِيرٍ، عَنْ سُفْيَانَ، حَدَّثَنَا مَنْصُورٌ، وَالأَعْمَشُ، عَنْ أَبِي الضُّحَى، عَنْ مَسْرُوقٍ، قَالَ أَتَيْتُ ابْنَ مَسْعُودٍ فَقَالَ إِنَّ قُرَيْشًا أَبْطَئُوا عَنِ الإِسْلاَمِ،، فَدَعَا عَلَيْهِمُ النَّبِيُّ صلى الله عليه وسلم فَأَخَذَتْهُمْ سَنَةٌ حَتَّى هَلَكُوا فِيهَا وَأَكَلُوا الْمَيْتَةَ وَالْعِظَامَ، فَجَاءَهُ أَبُو سُفْيَانَ فَقَالَ يَا مُحَمَّدُ، جِئْتَ تَأْمُرُ بِصِلَةِ الرَّحِمِ، وَإِنَّ قَوْمَكَ هَلَكُوا، فَادْعُ اللَّهَ‏.‏ فَقَرَأَ ‏{‏فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ‏}‏ ثُمَّ عَادُوا إِلَى كُفْرِهِمْ فَذَلِكَ قَوْلُهُ تَعَالَى ‏{‏يَوْمَ نَبْطِشُ الْبَطْشَةَ الْكُبْرَى‏}‏ يَوْمَ بَدْرٍ‏.‏ قَالَ وَزَادَ أَسْبَاطٌ عَنْ مَنْصُورٍ فَدَعَا رَسُولُ اللَّهِ صلى الله عليه وسلم، فَسُقُوا الْغَيْثَ، فَأَطْبَقَتْ عَلَيْهِمْ سَبْعًا، وَشَكَا النَّاسُ كَثْرَةَ الْمَطَرِ فَقَالَ ‏\"‏ اللَّهُمَّ حَوَالَيْنَا وَلاَ عَلَيْنَا ‏\"‏‏.‏ فَانْحَدَرَتِ السَّحَابَةُ عَنْ رَأْسِهِ، فَسُقُوا النَّاسُ حَوْلَهُمْ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4774","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4774","x":"Narrated Masruq:\n\nWhile a man was delivering a speech in the tribe of Kinda, he said, \"Smoke will prevail on the Day of Resurrection and will deprive the hypocrites their faculties of hearing and seeing. The believers will be afflicted with something like cold only thereof.\" That news scared us, so I went to (Abdullah) Ibn Mas`ud while he was reclining (and told him the story) whereupon he became angry, sat up and said, \"He who knows a thing can say, it, but if he does not know, he should say, 'Allah knows best,' for it is an aspect of knowledge to say, 'I do not know,' if you do not know a certain thing. Allah said to His prophet. 'Say (O Muhammad): No wage do I ask of you for this (Qur'an), nor I am one of the pretenders (a person who pretends things which do not exist.)' (38.86) The Qur'aish delayed in embracing Islam for a period, so the Prophet (ﷺ) invoked evil on them, saying, 'O Allah! Help me against them by sending seven years of (famine) like those of Joseph.' So they were afflicted with such a severe year of famine that they were destroyed therein and ate dead animals and bones. They started seeing something like smoke between the sky and the earth (because of severe hunger). Abu Sufyan then came (to the Prophet) and said, \"O Muhammad! You came to order us for to keep good relations with Kith and kin, and your kinsmen have now perished, so please invoke Allah (to relieve them).' Then Ibn Mas`ud recited:-- 'Then watch you for the day that the sky will bring forth a kind of smoke plainly visible....but truly you will return! (to disbelief) (44.10-15) Ibn Mas`ud added, Then the punishment was stopped, but truly, they reverted to heathenism (their old way). So Allah (threatened them thus): 'On the day when we shall seize you with a mighty grasp.' (44.16) And that was the day of the Battle of Badr. Allah's saying- \"Lizama\" (the punishment) refers to the day of Badr Allah's Statement: Alif-Lam-Mim, the Romans have been defeated, and they, after their defeat, will be victorious,' (30.1- 3) (This verse): Indicates that the defeat of Byzantine has already passed.","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ كَثِيرٍ، حَدَّثَنَا سُفْيَانُ، حَدَّثَنَا مَنْصُورٌ، وَالأَعْمَشُ، عَنْ أَبِي الضُّحَى، عَنْ مَسْرُوقٍ، قَالَ بَيْنَمَا رَجُلٌ يُحَدِّثُ فِي كِنْدَةَ فَقَالَ يَجِيءُ دُخَانٌ يَوْمَ الْقِيَامَةِ فَيَأْخُذُ بِأَسْمَاعِ الْمُنَافِقِينَ وَأَبْصَارِهِمْ، يَأْخُذُ الْمُؤْمِنَ كَهَيْئَةِ الزُّكَامِ‏.‏ فَفَزِعْنَا، فَأَتَيْتُ ابْنَ مَسْعُودٍ، وَكَانَ مُتَّكِئًا، فَغَضِبَ فَجَلَسَ فَقَالَ مَنْ عَلِمَ فَلْيَقُلْ، وَمَنْ لَمْ يَعْلَمْ فَلْيَقُلِ اللَّهُ أَعْلَمُ‏.‏ فَإِنَّ مِنَ الْعِلْمِ أَنْ يَقُولَ لِمَا لاَ يَعْلَمُ لاَ أَعْلَمُ‏.‏ فَإِنَّ اللَّهَ قَالَ لِنَبِيِّهِ صلى الله عليه وسلم ‏{‏قُلْ مَا أَسْأَلُكُمْ عَلَيْهِ مِنْ أَجْرٍ وَمَا أَنَا مِنَ الْمُتَكَلِّفِينَ‏}‏ وَإِنَّ قُرَيْشًا أَبْطَئُوا عَنِ الإِسْلاَمِ فَدَعَا عَلَيْهِمِ النَّبِيُّ صلى الله عليه وسلم فَقَالَ ‏\"‏ اللَّهُمَّ أَعِنِّي عَلَيْهِمْ بِسَبْعٍ كَسَبْعِ يُوسُفَ، فَأَخَذَتْهُمْ سَنَةٌ حَتَّى هَلَكُوا فِيهَا، وَأَكَلُوا الْمَيْتَةَ وَالْعِظَامَ وَيَرَى الرَّجُلُ مَا بَيْنَ السَّمَاءِ وَالأَرْضِ كَهَيْئَةِ الدُّخَانِ ‏\"‏، فَجَاءَهُ أَبُو سُفْيَانَ فَقَالَ يَا مُحَمَّدُ جِئْتَ تَأْمُرُنَا بِصِلَةِ الرَّحِمِ، وَإِنَّ قَوْمَكَ قَدْ هَلَكُوا فَادْعُ اللَّهَ، فَقَرَأَ ‏{‏فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ‏}‏ إِلَى قَوْلِهِ ‏{‏عَائِدُونَ‏}‏ أَفَيُكْشَفُ عَنْهُمْ عَذَابُ الآخِرَةِ إِذَا جَاءَ ثُمَّ عَادُوا إِلَى كُفْرِهِمْ فَذَلِكَ قَوْلُهُ تَعَالَى ‏{‏يَوْمَ نَبْطِشُ الْبَطْشَةَ الْكُبْرَى‏}‏ يَوْمَ بَدْرٍ وَلِزَامًا يَوْمَ بَدْرٍ ‏{‏الم * غُلِبَتِ الرُّومُ‏}‏ إِلَى ‏{‏سَيَغْلِبُونَ‏}‏ وَالرُّومُ قَدْ مَضَى‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4809","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4809","x":"Narrated Masruq:\n\nWe came upon `Abdullah bin Mas`ud and he said \"O people! If somebody knows something, he can say it, but if he does not know it, he should say, \"Allah knows better,' for it is a sign of having knowledge to say about something which one does not know, 'Allah knows better.' Allah said to His Prophet: 'Say (O Muhammad ! ) No wage do I ask of You for this (Qur'an) nor am I one of the pretenders (a person who pretends things which do not exist).' (38.86) Now I will tell you about Ad- Dukhan (the smoke), Allah's Messenger (ﷺ) invited the Quraish to embrace Islam, but they delayed their response. So he said, \"O Allah! Help me against them by sending on them seven years of famine similar to the seven years of famine of Joseph.\" So the famine year overtook them and everything was destroyed till they ate dead animals and skins. People started imagining to see smoke between them and the sky because of severe hunger. Allah said: 'Then watch you for the Day that the sky will bring forth a kind of smoke plainly visible, covering the people... This is painful torment.' (44.10-11) (So they invoked Allah) \"Our Lord! Remove the punishment from us really we are believers.\" How can there be an (effectual) reminder for them when an Apostle, explaining things clearly, has already come to them? Then they had turned away from him and said: 'One taught (by a human being), a madman?' 'We shall indeed remove punishment for a while, but truly, you will revert (to disbelief).' (44.12-15) Will the punishment be removed on the Day of Resurrection?\" `Abdullah added, \"The punishment was removed from them for a while but they reverted to disbelief, so Allah destroyed them on the Day of Badr. Allah said: 'The day We shall seize you with a mighty grasp. We will indeed (then) exact retribution.\" (44.16)","ar":"حَدَّثَنَا قُتَيْبَةُ، حَدَّثَنَا جَرِيرٌ، عَنِ الأَعْمَشِ، عَنْ أَبِي الضُّحَى، عَنْ مَسْرُوقٍ، قَالَ دَخَلْنَا عَلَى عَبْدِ اللَّهِ بْنِ مَسْعُودٍ، قَالَ يَا أَيُّهَا النَّاسُ مَنْ عَلِمَ شَيْئًا فَلْيَقُلْ بِهِ، وَمَنْ لَمْ يَعْلَمْ فَلْيَقُلِ اللَّهُ أَعْلَمُ، فَإِنَّ مِنَ الْعِلْمِ أَنْ يَقُولَ لِمَا لاَ يَعْلَمُ اللَّهُ أَعْلَمُ، قَالَ اللَّهُ عَزَّ وَجَلَّ لِنَبِيِّهِ صلى الله عليه وسلم ‏{‏قُلْ مَا أَسْأَلُكُمْ عَلَيْهِ مِنْ أَجْرٍ وَمَا أَنَا مِنَ الْمُتَكَلِّفِينَ‏}‏ وَسَأُحَدِّثُكُمْ عَنِ الدُّخَانِ إِنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم دَعَا قُرَيْشًا إِلَى الإِسْلاَمِ فَأَبْطَئُوا عَلَيْهِ فَقَالَ ‏\"‏ اللَّهُمَّ أَعِنِّي عَلَيْهِمْ بِسَبْعٍ كَسَبْعِ يُوسُفَ ‏\"‏، فَأَخَذَتْهُمْ سَنَةٌ فَحَصَّتْ كُلَّ شَىْءٍ حَتَّى أَكَلُوا الْمَيْتَةَ وَالْجُلُودَ حَتَّى جَعَلَ الرَّجُلُ يَرَى بَيْنَهُ وَبَيْنَ السَّمَاءِ دُخَانًا مِنَ الْجُوعِ، قَالَ اللَّهُ عَزَّ وَجَلَّ ‏{‏فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ * يَغْشَى النَّاسَ هَذَا عَذَابٌ أَلِيمٌ‏}‏ قَالَ فَدَعَوْا ‏{‏رَبَّنَا اكْشِفْ عَنَّا الْعَذَابَ إِنَّا مُؤْمِنُونَ * أَنَّى لَهُمُ الذِّكْرَى وَقَدْ جَاءَهُمْ رَسُولٌ مُبِينٌ * ثُمَّ تَوَلَّوْا عَنْهُ وَقَالُوا مُعَلَّمٌ مَجْنُونٌ * إِنَّا كَاشِفُو الْعَذَابِ قَلِيلاً إِنَّكُمْ عَائِدُونَ‏}‏ أَفَيُكْشَفُ الْعَذَابُ يَوْمَ الْقِيَامَةِ قَالَ فَكُشِفَ ثُمَّ عَادُوا فِي كُفْرِهِمْ، فَأَخَذَهُمُ اللَّهُ يَوْمَ بَدْرٍ قَالَ اللَّهُ تَعَالَى ‏{‏يَوْمَ نَبْطِشُ الْبَطْشَةَ الْكُبْرَى إِنَّا مُنْتَقِمُونَ‏}‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4823","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4823","x":"Narrated Masruq:\n\nI came upon `Abdullah and he said, \"When Allah's Messenger (ﷺ) invited Quraish (to Islam), they disbelieved him and stood against him. So he (the Prophet) said, \"O Allah! Help me against them by afflicting them with seven years of famine similar to the seven years of Joseph.' So they were stricken with a year of drought that destroyed everything, and they started eating dead animals, and if one of them got up he would see something like smoke between him and the sky from the severe fatigue and hunger.\" `Abdullah then recited:-- 'Then watch you for the Day that the sky will bring forth a kind of smoke plainly visible, covering the people. This is a painful torment... (till he reached)........ We shall indeed remove the punishment for a while, but truly you will revert (to heathenism): (44.10-15) `Abdullah added: \"Will the punishment be removed from them on the Day of Resurrection?\" He added,\" The severe grasp\" was the Day of the Battle of Badr.\"","ar":"حَدَّثَنَا سُلَيْمَانُ بْنُ حَرْبٍ، حَدَّثَنَا جَرِيرُ بْنُ حَازِمٍ، عَنِ الأَعْمَشِ، عَنْ أَبِي الضُّحَى، عَنْ مَسْرُوقٍ، قَالَ دَخَلْتُ عَلَى عَبْدِ اللَّهِ ثُمَّ قَالَ إِنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم لَمَّا دَعَا قُرَيْشًا كَذَّبُوهُ وَاسْتَعْصَوْا عَلَيْهِ فَقَالَ ‏\"‏ اللَّهُمَّ أَعِنِّي عَلَيْهِمْ بِسَبْعٍ كَسَبْعِ يُوسُفَ ‏\"‏‏.‏ فَأَصَابَتْهُمْ سَنَةٌ حَصَّتْ ـ يَعْنِي ـ كُلَّ شَىْءٍ حَتَّى كَانُوا يَأْكُلُونَ الْمَيْتَةَ فَكَانَ يَقُومُ أَحَدُهُمْ فَكَانَ يَرَى بَيْنَهُ وَبَيْنَ السَّمَاءِ مِثْلَ الدُّخَانِ مِنَ الْجَهْدِ وَالْجُوعِ ثُمَّ قَرَأَ ‏{‏فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ * يَغْشَى النَّاسَ هَذَا عَذَابٌ أَلِيمٌ‏}‏ حَتَّى بَلَغَ ‏{‏إِنَّا كَاشِفُو الْعَذَابِ قَلِيلاً إِنَّكُمْ عَائِدُونَ‏}‏ قَالَ عَبْدُ اللَّهِ أَفَيُكْشَفُ عَنْهُمُ الْعَذَابُ يَوْمَ الْقِيَامَةِ قَالَ وَالْبَطْشَةُ الْكُبْرَى يَوْمَ بَدْرٍ‏.‏","v":[]}],"14":[{"c":"Sahih Bukhari","r":"Hadith 1007","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-1007","x":"Narrated Masruq:\n\nWe were with `Abdullah and he said, \"When the Prophet (ﷺ) saw the refusal of the people to accept Islam he said, \"O Allah! Send (famine) years on them for (seven years) like the seven years (of famine during the time) of (Prophet) Joseph.\" So famine overtook them for one year and destroyed every kind of life to such an extent that the people started eating hides, carcasses and rotten dead animals. Whenever one of them looked towards the sky, he would (imagine himself to) see smoke because of hunger. So Abu Sufyan went to the Prophet (ﷺ) and said, \"O Muhammad! You order people to obey Allah and to keep good relations with kith and kin. No doubt the people of your tribe are dying, so please pray to Allah for them.\" So Allah revealed: \"Then watch you For the day that The sky will bring forth a kind Of smoke Plainly visible... Verily! You will return (to disbelief) On the day when We shall seize You with a mighty grasp. (44.10-16) Ibn Mas`ud added, \"Al-Batsha (i.e. grasp) happened in the battle of Badr and no doubt smoke, Al-Batsha, Al-Lizam, and the verse of Surat Ar-Rum have all passed.","ar":"حَدَّثَنَا عُثْمَانُ بْنُ أَبِي شَيْبَةَ، قَالَ حَدَّثَنَا جَرِيرٌ، عَنْ مَنْصُورٍ، عَنْ أَبِي الضُّحَى، عَنْ مَسْرُوقٍ، قَالَ كُنَّا عِنْدَ عَبْدِ اللَّهِ فَقَالَ إِنَّ النَّبِيَّ صلى الله عليه وسلم لَمَّا رَأَى مِنَ النَّاسِ إِدْبَارًا قَالَ ‏\"‏ اللَّهُمَّ سَبْعٌ كَسَبْعِ يُوسُفَ ‏\"‏‏.‏ فَأَخَذَتْهُمْ سَنَةٌ حَصَّتْ كُلَّ شَىْءٍ حَتَّى أَكَلُوا الْجُلُودَ وَالْمَيْتَةَ وَالْجِيَفَ، وَيَنْظُرَ أَحَدُهُمْ إِلَى السَّمَاءِ فَيَرَى الدُّخَانَ مِنَ الْجُوعِ، فَأَتَاهُ أَبُو سُفْيَانَ فَقَالَ يَا مُحَمَّدُ إِنَّكَ تَأْمُرُ بِطَاعَةِ اللَّهِ وَبِصِلَةِ الرَّحِمِ وَإِنَّ قَوْمَكَ قَدْ هَلَكُوا، فَادْعُ اللَّهَ لَهُمْ قَالَ اللَّهُ تَعَالَى ‏{‏فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ‏}‏ إِلَى قَوْلِهِ ‏{‏عَائِدُونَ * يَوْمَ نَبْطِشُ الْبَطْشَةَ الْكُبْرَى‏}‏ فَالْبَطْشَةُ يَوْمَ بَدْرٍ، وَقَدْ مَضَتِ الدُّخَانُ وَالْبَطْشَةُ وَاللِّزَامُ وَآيَةُ الرُّومِ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 1020","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-1020","x":"Narrated Masruq:\n\nOne day I went to Ibn Mas`ud who said, \"When Quraish delayed in embracing Islam, the Prophet (ﷺ) I invoked Allah to curse them, so they were afflicted with a (famine) year because of which many of them died and they ate the carcasses and Abu Sufyan came to the Prophet (ﷺ) and said, 'O Muhammad! You came to order people to keep good relation with kith and kin and your nation is being destroyed, so invoke Allah I ? So the Prophet (ﷺ) I recited the Holy verses of Sirat-Ad-Dukhan: 'Then watch you For the day that The sky will Bring forth a kind Of smoke Plainly visible.' (44.10) When the famine was taken off, the people renegade once again as nonbelievers. The statement of Allah, (in Sura \"Ad- Dukhan\"-44) refers to that: 'On the day when We shall seize You with a mighty grasp.' (44.16) And that was what happened on the day of the battle of Badr.\" Asbath added on the authority of Mansur, \"Allah's Messenger (ﷺ) prayed for them and it rained heavily for seven days. So the people complained of the excessive rain. The Prophet (ﷺ) said, 'O Allah! (Let it rain) around us and not on us.' So the clouds dispersed over his head and it rained over the surroundings.\"","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ كَثِيرٍ، عَنْ سُفْيَانَ، حَدَّثَنَا مَنْصُورٌ، وَالأَعْمَشُ، عَنْ أَبِي الضُّحَى، عَنْ مَسْرُوقٍ، قَالَ أَتَيْتُ ابْنَ مَسْعُودٍ فَقَالَ إِنَّ قُرَيْشًا أَبْطَئُوا عَنِ الإِسْلاَمِ،، فَدَعَا عَلَيْهِمُ النَّبِيُّ صلى الله عليه وسلم فَأَخَذَتْهُمْ سَنَةٌ حَتَّى هَلَكُوا فِيهَا وَأَكَلُوا الْمَيْتَةَ وَالْعِظَامَ، فَجَاءَهُ أَبُو سُفْيَانَ فَقَالَ يَا مُحَمَّدُ، جِئْتَ تَأْمُرُ بِصِلَةِ الرَّحِمِ، وَإِنَّ قَوْمَكَ هَلَكُوا، فَادْعُ اللَّهَ‏.‏ فَقَرَأَ ‏{‏فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ‏}‏ ثُمَّ عَادُوا إِلَى كُفْرِهِمْ فَذَلِكَ قَوْلُهُ تَعَالَى ‏{‏يَوْمَ نَبْطِشُ الْبَطْشَةَ الْكُبْرَى‏}‏ يَوْمَ بَدْرٍ‏.‏ قَالَ وَزَادَ أَسْبَاطٌ عَنْ مَنْصُورٍ فَدَعَا رَسُولُ اللَّهِ صلى الله عليه وسلم، فَسُقُوا الْغَيْثَ، فَأَطْبَقَتْ عَلَيْهِمْ سَبْعًا، وَشَكَا النَّاسُ كَثْرَةَ الْمَطَرِ فَقَالَ ‏\"‏ اللَّهُمَّ حَوَالَيْنَا وَلاَ عَلَيْنَا ‏\"‏‏.‏ فَانْحَدَرَتِ السَّحَابَةُ عَنْ رَأْسِهِ، فَسُقُوا النَّاسُ حَوْلَهُمْ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4774","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4774","x":"Narrated Masruq:\n\nWhile a man was delivering a speech in the tribe of Kinda, he said, \"Smoke will prevail on the Day of Resurrection and will deprive the hypocrites their faculties of hearing and seeing. The believers will be afflicted with something like cold only thereof.\" That news scared us, so I went to (Abdullah) Ibn Mas`ud while he was reclining (and told him the story) whereupon he became angry, sat up and said, \"He who knows a thing can say, it, but if he does not know, he should say, 'Allah knows best,' for it is an aspect of knowledge to say, 'I do not know,' if you do not know a certain thing. Allah said to His prophet. 'Say (O Muhammad): No wage do I ask of you for this (Qur'an), nor I am one of the pretenders (a person who pretends things which do not exist.)' (38.86) The Qur'aish delayed in embracing Islam for a period, so the Prophet (ﷺ) invoked evil on them, saying, 'O Allah! Help me against them by sending seven years of (famine) like those of Joseph.' So they were afflicted with such a severe year of famine that they were destroyed therein and ate dead animals and bones. They started seeing something like smoke between the sky and the earth (because of severe hunger). Abu Sufyan then came (to the Prophet) and said, \"O Muhammad! You came to order us for to keep good relations with Kith and kin, and your kinsmen have now perished, so please invoke Allah (to relieve them).' Then Ibn Mas`ud recited:-- 'Then watch you for the day that the sky will bring forth a kind of smoke plainly visible....but truly you will return! (to disbelief) (44.10-15) Ibn Mas`ud added, Then the punishment was stopped, but truly, they reverted to heathenism (their old way). So Allah (threatened them thus): 'On the day when we shall seize you with a mighty grasp.' (44.16) And that was the day of the Battle of Badr. Allah's saying- \"Lizama\" (the punishment) refers to the day of Badr Allah's Statement: Alif-Lam-Mim, the Romans have been defeated, and they, after their defeat, will be victorious,' (30.1- 3) (This verse): Indicates that the defeat of Byzantine has already passed.","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ كَثِيرٍ، حَدَّثَنَا سُفْيَانُ، حَدَّثَنَا مَنْصُورٌ، وَالأَعْمَشُ، عَنْ أَبِي الضُّحَى، عَنْ مَسْرُوقٍ، قَالَ بَيْنَمَا رَجُلٌ يُحَدِّثُ فِي كِنْدَةَ فَقَالَ يَجِيءُ دُخَانٌ يَوْمَ الْقِيَامَةِ فَيَأْخُذُ بِأَسْمَاعِ الْمُنَافِقِينَ وَأَبْصَارِهِمْ، يَأْخُذُ الْمُؤْمِنَ كَهَيْئَةِ الزُّكَامِ‏.‏ فَفَزِعْنَا، فَأَتَيْتُ ابْنَ مَسْعُودٍ، وَكَانَ مُتَّكِئًا، فَغَضِبَ فَجَلَسَ فَقَالَ مَنْ عَلِمَ فَلْيَقُلْ، وَمَنْ لَمْ يَعْلَمْ فَلْيَقُلِ اللَّهُ أَعْلَمُ‏.‏ فَإِنَّ مِنَ الْعِلْمِ أَنْ يَقُولَ لِمَا لاَ يَعْلَمُ لاَ أَعْلَمُ‏.‏ فَإِنَّ اللَّهَ قَالَ لِنَبِيِّهِ صلى الله عليه وسلم ‏{‏قُلْ مَا أَسْأَلُكُمْ عَلَيْهِ مِنْ أَجْرٍ وَمَا أَنَا مِنَ الْمُتَكَلِّفِينَ‏}‏ وَإِنَّ قُرَيْشًا أَبْطَئُوا عَنِ الإِسْلاَمِ فَدَعَا عَلَيْهِمِ النَّبِيُّ صلى الله عليه وسلم فَقَالَ ‏\"‏ اللَّهُمَّ أَعِنِّي عَلَيْهِمْ بِسَبْعٍ كَسَبْعِ يُوسُفَ، فَأَخَذَتْهُمْ سَنَةٌ حَتَّى هَلَكُوا فِيهَا، وَأَكَلُوا الْمَيْتَةَ وَالْعِظَامَ وَيَرَى الرَّجُلُ مَا بَيْنَ السَّمَاءِ وَالأَرْضِ كَهَيْئَةِ الدُّخَانِ ‏\"‏، فَجَاءَهُ أَبُو سُفْيَانَ فَقَالَ يَا مُحَمَّدُ جِئْتَ تَأْمُرُنَا بِصِلَةِ الرَّحِمِ، وَإِنَّ قَوْمَكَ قَدْ هَلَكُوا فَادْعُ اللَّهَ، فَقَرَأَ ‏{‏فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ‏}‏ إِلَى قَوْلِهِ ‏{‏عَائِدُونَ‏}‏ أَفَيُكْشَفُ عَنْهُمْ عَذَابُ الآخِرَةِ إِذَا جَاءَ ثُمَّ عَادُوا إِلَى كُفْرِهِمْ فَذَلِكَ قَوْلُهُ تَعَالَى ‏{‏يَوْمَ نَبْطِشُ الْبَطْشَةَ الْكُبْرَى‏}‏ يَوْمَ بَدْرٍ وَلِزَامًا يَوْمَ بَدْرٍ ‏{‏الم * غُلِبَتِ الرُّومُ‏}‏ إِلَى ‏{‏سَيَغْلِبُونَ‏}‏ وَالرُّومُ قَدْ مَضَى‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4809","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4809","x":"Narrated Masruq:\n\nWe came upon `Abdullah bin Mas`ud and he said \"O people! If somebody knows something, he can say it, but if he does not know it, he should say, \"Allah knows better,' for it is a sign of having knowledge to say about something which one does not know, 'Allah knows better.' Allah said to His Prophet: 'Say (O Muhammad ! ) No wage do I ask of You for this (Qur'an) nor am I one of the pretenders (a person who pretends things which do not exist).' (38.86) Now I will tell you about Ad- Dukhan (the smoke), Allah's Messenger (ﷺ) invited the Quraish to embrace Islam, but they delayed their response. So he said, \"O Allah! Help me against them by sending on them seven years of famine similar to the seven years of famine of Joseph.\" So the famine year overtook them and everything was destroyed till they ate dead animals and skins. People started imagining to see smoke between them and the sky because of severe hunger. Allah said: 'Then watch you for the Day that the sky will bring forth a kind of smoke plainly visible, covering the people... This is painful torment.' (44.10-11) (So they invoked Allah) \"Our Lord! Remove the punishment from us really we are believers.\" How can there be an (effectual) reminder for them when an Apostle, explaining things clearly, has already come to them? Then they had turned away from him and said: 'One taught (by a human being), a madman?' 'We shall indeed remove punishment for a while, but truly, you will revert (to disbelief).' (44.12-15) Will the punishment be removed on the Day of Resurrection?\" `Abdullah added, \"The punishment was removed from them for a while but they reverted to disbelief, so Allah destroyed them on the Day of Badr. Allah said: 'The day We shall seize you with a mighty grasp. We will indeed (then) exact retribution.\" (44.16)","ar":"حَدَّثَنَا قُتَيْبَةُ، حَدَّثَنَا جَرِيرٌ، عَنِ الأَعْمَشِ، عَنْ أَبِي الضُّحَى، عَنْ مَسْرُوقٍ، قَالَ دَخَلْنَا عَلَى عَبْدِ اللَّهِ بْنِ مَسْعُودٍ، قَالَ يَا أَيُّهَا النَّاسُ مَنْ عَلِمَ شَيْئًا فَلْيَقُلْ بِهِ، وَمَنْ لَمْ يَعْلَمْ فَلْيَقُلِ اللَّهُ أَعْلَمُ، فَإِنَّ مِنَ الْعِلْمِ أَنْ يَقُولَ لِمَا لاَ يَعْلَمُ اللَّهُ أَعْلَمُ، قَالَ اللَّهُ عَزَّ وَجَلَّ لِنَبِيِّهِ صلى الله عليه وسلم ‏{‏قُلْ مَا أَسْأَلُكُمْ عَلَيْهِ مِنْ أَجْرٍ وَمَا أَنَا مِنَ الْمُتَكَلِّفِينَ‏}‏ وَسَأُحَدِّثُكُمْ عَنِ الدُّخَانِ إِنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم دَعَا قُرَيْشًا إِلَى الإِسْلاَمِ فَأَبْطَئُوا عَلَيْهِ فَقَالَ ‏\"‏ اللَّهُمَّ أَعِنِّي عَلَيْهِمْ بِسَبْعٍ كَسَبْعِ يُوسُفَ ‏\"‏، فَأَخَذَتْهُمْ سَنَةٌ فَحَصَّتْ كُلَّ شَىْءٍ حَتَّى أَكَلُوا الْمَيْتَةَ وَالْجُلُودَ حَتَّى جَعَلَ الرَّجُلُ يَرَى بَيْنَهُ وَبَيْنَ السَّمَاءِ دُخَانًا مِنَ الْجُوعِ، قَالَ اللَّهُ عَزَّ وَجَلَّ ‏{‏فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ * يَغْشَى النَّاسَ هَذَا عَذَابٌ أَلِيمٌ‏}‏ قَالَ فَدَعَوْا ‏{‏رَبَّنَا اكْشِفْ عَنَّا الْعَذَابَ إِنَّا مُؤْمِنُونَ * أَنَّى لَهُمُ الذِّكْرَى وَقَدْ جَاءَهُمْ رَسُولٌ مُبِينٌ * ثُمَّ تَوَلَّوْا عَنْهُ وَقَالُوا مُعَلَّمٌ مَجْنُونٌ * إِنَّا كَاشِفُو الْعَذَابِ قَلِيلاً إِنَّكُمْ عَائِدُونَ‏}‏ أَفَيُكْشَفُ الْعَذَابُ يَوْمَ الْقِيَامَةِ قَالَ فَكُشِفَ ثُمَّ عَادُوا فِي كُفْرِهِمْ، فَأَخَذَهُمُ اللَّهُ يَوْمَ بَدْرٍ قَالَ اللَّهُ تَعَالَى ‏{‏يَوْمَ نَبْطِشُ الْبَطْشَةَ الْكُبْرَى إِنَّا مُنْتَقِمُونَ‏}‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4823","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4823","x":"Narrated Masruq:\n\nI came upon `Abdullah and he said, \"When Allah's Messenger (ﷺ) invited Quraish (to Islam), they disbelieved him and stood against him. So he (the Prophet) said, \"O Allah! Help me against them by afflicting them with seven years of famine similar to the seven years of Joseph.' So they were stricken with a year of drought that destroyed everything, and they started eating dead animals, and if one of them got up he would see something like smoke between him and the sky from the severe fatigue and hunger.\" `Abdullah then recited:-- 'Then watch you for the Day that the sky will bring forth a kind of smoke plainly visible, covering the people. This is a painful torment... (till he reached)........ We shall indeed remove the punishment for a while, but truly you will revert (to heathenism): (44.10-15) `Abdullah added: \"Will the punishment be removed from them on the Day of Resurrection?\" He added,\" The severe grasp\" was the Day of the Battle of Badr.\"","ar":"حَدَّثَنَا سُلَيْمَانُ بْنُ حَرْبٍ، حَدَّثَنَا جَرِيرُ بْنُ حَازِمٍ، عَنِ الأَعْمَشِ، عَنْ أَبِي الضُّحَى، عَنْ مَسْرُوقٍ، قَالَ دَخَلْتُ عَلَى عَبْدِ اللَّهِ ثُمَّ قَالَ إِنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم لَمَّا دَعَا قُرَيْشًا كَذَّبُوهُ وَاسْتَعْصَوْا عَلَيْهِ فَقَالَ ‏\"‏ اللَّهُمَّ أَعِنِّي عَلَيْهِمْ بِسَبْعٍ كَسَبْعِ يُوسُفَ ‏\"‏‏.‏ فَأَصَابَتْهُمْ سَنَةٌ حَصَّتْ ـ يَعْنِي ـ كُلَّ شَىْءٍ حَتَّى كَانُوا يَأْكُلُونَ الْمَيْتَةَ فَكَانَ يَقُومُ أَحَدُهُمْ فَكَانَ يَرَى بَيْنَهُ وَبَيْنَ السَّمَاءِ مِثْلَ الدُّخَانِ مِنَ الْجَهْدِ وَالْجُوعِ ثُمَّ قَرَأَ ‏{‏فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ * يَغْشَى النَّاسَ هَذَا عَذَابٌ أَلِيمٌ‏}‏ حَتَّى بَلَغَ ‏{‏إِنَّا كَاشِفُو الْعَذَابِ قَلِيلاً إِنَّكُمْ عَائِدُونَ‏}‏ قَالَ عَبْدُ اللَّهِ أَفَيُكْشَفُ عَنْهُمُ الْعَذَابُ يَوْمَ الْقِيَامَةِ قَالَ وَالْبَطْشَةُ الْكُبْرَى يَوْمَ بَدْرٍ‏.‏","v":[]}],"15":[{"c":"Sahih Bukhari","r":"Hadith 1007","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-1007","x":"Narrated Masruq:\n\nWe were with `Abdullah and he said, \"When the Prophet (ﷺ) saw the refusal of the people to accept Islam he said, \"O Allah! Send (famine) years on them for (seven years) like the seven years (of famine during the time) of (Prophet) Joseph.\" So famine overtook them for one year and destroyed every kind of life to such an extent that the people started eating hides, carcasses and rotten dead animals. Whenever one of them looked towards the sky, he would (imagine himself to) see smoke because of hunger. So Abu Sufyan went to the Prophet (ﷺ) and said, \"O Muhammad! You order people to obey Allah and to keep good relations with kith and kin. No doubt the people of your tribe are dying, so please pray to Allah for them.\" So Allah revealed: \"Then watch you For the day that The sky will bring forth a kind Of smoke Plainly visible... Verily! You will return (to disbelief) On the day when We shall seize You with a mighty grasp. (44.10-16) Ibn Mas`ud added, \"Al-Batsha (i.e. grasp) happened in the battle of Badr and no doubt smoke, Al-Batsha, Al-Lizam, and the verse of Surat Ar-Rum have all passed.","ar":"حَدَّثَنَا عُثْمَانُ بْنُ أَبِي شَيْبَةَ، قَالَ حَدَّثَنَا جَرِيرٌ، عَنْ مَنْصُورٍ، عَنْ أَبِي الضُّحَى، عَنْ مَسْرُوقٍ، قَالَ كُنَّا عِنْدَ عَبْدِ اللَّهِ فَقَالَ إِنَّ النَّبِيَّ صلى الله عليه وسلم لَمَّا رَأَى مِنَ النَّاسِ إِدْبَارًا قَالَ ‏\"‏ اللَّهُمَّ سَبْعٌ كَسَبْعِ يُوسُفَ ‏\"‏‏.‏ فَأَخَذَتْهُمْ سَنَةٌ حَصَّتْ كُلَّ شَىْءٍ حَتَّى أَكَلُوا الْجُلُودَ وَالْمَيْتَةَ وَالْجِيَفَ، وَيَنْظُرَ أَحَدُهُمْ إِلَى السَّمَاءِ فَيَرَى الدُّخَانَ مِنَ الْجُوعِ، فَأَتَاهُ أَبُو سُفْيَانَ فَقَالَ يَا مُحَمَّدُ إِنَّكَ تَأْمُرُ بِطَاعَةِ اللَّهِ وَبِصِلَةِ الرَّحِمِ وَإِنَّ قَوْمَكَ قَدْ هَلَكُوا، فَادْعُ اللَّهَ لَهُمْ قَالَ اللَّهُ تَعَالَى ‏{‏فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ‏}‏ إِلَى قَوْلِهِ ‏{‏عَائِدُونَ * يَوْمَ نَبْطِشُ الْبَطْشَةَ الْكُبْرَى‏}‏ فَالْبَطْشَةُ يَوْمَ بَدْرٍ، وَقَدْ مَضَتِ الدُّخَانُ وَالْبَطْشَةُ وَاللِّزَامُ وَآيَةُ الرُّومِ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 1020","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-1020","x":"Narrated Masruq:\n\nOne day I went to Ibn Mas`ud who said, \"When Quraish delayed in embracing Islam, the Prophet (ﷺ) I invoked Allah to curse them, so they were afflicted with a (famine) year because of which many of them died and they ate the carcasses and Abu Sufyan came to the Prophet (ﷺ) and said, 'O Muhammad! You came to order people to keep good relation with kith and kin and your nation is being destroyed, so invoke Allah I ? So the Prophet (ﷺ) I recited the Holy verses of Sirat-Ad-Dukhan: 'Then watch you For the day that The sky will Bring forth a kind Of smoke Plainly visible.' (44.10) When the famine was taken off, the people renegade once again as nonbelievers. The statement of Allah, (in Sura \"Ad- Dukhan\"-44) refers to that: 'On the day when We shall seize You with a mighty grasp.' (44.16) And that was what happened on the day of the battle of Badr.\" Asbath added on the authority of Mansur, \"Allah's Messenger (ﷺ) prayed for them and it rained heavily for seven days. So the people complained of the excessive rain. The Prophet (ﷺ) said, 'O Allah! (Let it rain) around us and not on us.' So the clouds dispersed over his head and it rained over the surroundings.\"","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ كَثِيرٍ، عَنْ سُفْيَانَ، حَدَّثَنَا مَنْصُورٌ، وَالأَعْمَشُ، عَنْ أَبِي الضُّحَى، عَنْ مَسْرُوقٍ، قَالَ أَتَيْتُ ابْنَ مَسْعُودٍ فَقَالَ إِنَّ قُرَيْشًا أَبْطَئُوا عَنِ الإِسْلاَمِ،، فَدَعَا عَلَيْهِمُ النَّبِيُّ صلى الله عليه وسلم فَأَخَذَتْهُمْ سَنَةٌ حَتَّى هَلَكُوا فِيهَا وَأَكَلُوا الْمَيْتَةَ وَالْعِظَامَ، فَجَاءَهُ أَبُو سُفْيَانَ فَقَالَ يَا مُحَمَّدُ، جِئْتَ تَأْمُرُ بِصِلَةِ الرَّحِمِ، وَإِنَّ قَوْمَكَ هَلَكُوا، فَادْعُ اللَّهَ‏.‏ فَقَرَأَ ‏{‏فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ‏}‏ ثُمَّ عَادُوا إِلَى كُفْرِهِمْ فَذَلِكَ قَوْلُهُ تَعَالَى ‏{‏يَوْمَ نَبْطِشُ الْبَطْشَةَ الْكُبْرَى‏}‏ يَوْمَ بَدْرٍ‏.‏ قَالَ وَزَادَ أَسْبَاطٌ عَنْ مَنْصُورٍ فَدَعَا رَسُولُ اللَّهِ صلى الله عليه وسلم، فَسُقُوا الْغَيْثَ، فَأَطْبَقَتْ عَلَيْهِمْ سَبْعًا، وَشَكَا النَّاسُ كَثْرَةَ الْمَطَرِ فَقَالَ ‏\"‏ اللَّهُمَّ حَوَالَيْنَا وَلاَ عَلَيْنَا ‏\"‏‏.‏ فَانْحَدَرَتِ السَّحَابَةُ عَنْ رَأْسِهِ، فَسُقُوا النَّاسُ حَوْلَهُمْ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4693","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4693","x":"Narrated `Abdullah (bin Mas`ud):\n\nWhen the Prophet (ﷺ) realized that the Quraish had delayed in embracing Islam, he said, \"O Allah! Protect me against their evil by afflicting them with seven (years of famine) like the seven years of (Prophet) Joseph.\" So they were struck with a year of famine that destroyed everything till they had to eat bones, and till a man would look towards the sky and see something like smoke between him and it. Allah said:-- \"Then watch you (O Muhammad) for the day when the sky will produce a kind of smoke plainly visible.\" (44.10) And Allah further said:-- \"Verily! We shall withdraw the punishment a little, Verily you will return (to disbelief).\" (44.15) (Will Allah relieve them from torture on the Day of Resurrection?) (The punishment of) the smoke had passed and Al-Baltsha (the destruction of the pagans in the Badr battle) had passed too.","ar":"حَدَّثَنَا الْحُمَيْدِيُّ، حَدَّثَنَا سُفْيَانُ، عَنِ الأَعْمَشِ، عَنْ مُسْلِمٍ، عَنْ مَسْرُوقٍ، عَنْ عَبْدِ اللَّهِ ـ رضى الله عنه ـ أَنَّ قُرَيْشًا لَمَّا أَبْطَئُوا عَنِ النَّبِيِّ صلى الله عليه وسلم بِالإِسْلاَمِ قَالَ ‏\"‏ اللَّهُمَّ اكْفِنِيهِمْ بِسَبْعٍ كَسَبْعِ يُوسُفَ ‏\"‏ فَأَصَابَتْهُمْ سَنَةٌ حَصَّتْ كُلَّ شَىْءٍ حَتَّى أَكَلُوا الْعِظَامَ حَتَّى جَعَلَ الرَّجُلُ يَنْظُرُ إِلَى السَّمَاءِ فَيَرَى بَيْنَهُ وَبَيْنَهَا مِثْلَ الدُّخَانِ قَالَ اللَّهُ ‏{‏فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ‏}‏ قَالَ اللَّهُ ‏{‏إِنَّا كَاشِفُو الْعَذَابِ قَلِيلاً إِنَّكُمْ عَائِدُونَ‏}‏ أَفَيُكْشَفُ عَنْهُمُ الْعَذَابُ يَوْمَ الْقِيَامَةِ، وَقَدْ مَضَى الدُّخَانُ وَمَضَتِ الْبَطْشَةُ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4774","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4774","x":"Narrated Masruq:\n\nWhile a man was delivering a speech in the tribe of Kinda, he said, \"Smoke will prevail on the Day of Resurrection and will deprive the hypocrites their faculties of hearing and seeing. The believers will be afflicted with something like cold only thereof.\" That news scared us, so I went to (Abdullah) Ibn Mas`ud while he was reclining (and told him the story) whereupon he became angry, sat up and said, \"He who knows a thing can say, it, but if he does not know, he should say, 'Allah knows best,' for it is an aspect of knowledge to say, 'I do not know,' if you do not know a certain thing. Allah said to His prophet. 'Say (O Muhammad): No wage do I ask of you for this (Qur'an), nor I am one of the pretenders (a person who pretends things which do not exist.)' (38.86) The Qur'aish delayed in embracing Islam for a period, so the Prophet (ﷺ) invoked evil on them, saying, 'O Allah! Help me against them by sending seven years of (famine) like those of Joseph.' So they were afflicted with such a severe year of famine that they were destroyed therein and ate dead animals and bones. They started seeing something like smoke between the sky and the earth (because of severe hunger). Abu Sufyan then came (to the Prophet) and said, \"O Muhammad! You came to order us for to keep good relations with Kith and kin, and your kinsmen have now perished, so please invoke Allah (to relieve them).' Then Ibn Mas`ud recited:-- 'Then watch you for the day that the sky will bring forth a kind of smoke plainly visible....but truly you will return! (to disbelief) (44.10-15) Ibn Mas`ud added, Then the punishment was stopped, but truly, they reverted to heathenism (their old way). So Allah (threatened them thus): 'On the day when we shall seize you with a mighty grasp.' (44.16) And that was the day of the Battle of Badr. Allah's saying- \"Lizama\" (the punishment) refers to the day of Badr Allah's Statement: Alif-Lam-Mim, the Romans have been defeated, and they, after their defeat, will be victorious,' (30.1- 3) (This verse): Indicates that the defeat of Byzantine has already passed.","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ كَثِيرٍ، حَدَّثَنَا سُفْيَانُ، حَدَّثَنَا مَنْصُورٌ، وَالأَعْمَشُ، عَنْ أَبِي الضُّحَى، عَنْ مَسْرُوقٍ، قَالَ بَيْنَمَا رَجُلٌ يُحَدِّثُ فِي كِنْدَةَ فَقَالَ يَجِيءُ دُخَانٌ يَوْمَ الْقِيَامَةِ فَيَأْخُذُ بِأَسْمَاعِ الْمُنَافِقِينَ وَأَبْصَارِهِمْ، يَأْخُذُ الْمُؤْمِنَ كَهَيْئَةِ الزُّكَامِ‏.‏ فَفَزِعْنَا، فَأَتَيْتُ ابْنَ مَسْعُودٍ، وَكَانَ مُتَّكِئًا، فَغَضِبَ فَجَلَسَ فَقَالَ مَنْ عَلِمَ فَلْيَقُلْ، وَمَنْ لَمْ يَعْلَمْ فَلْيَقُلِ اللَّهُ أَعْلَمُ‏.‏ فَإِنَّ مِنَ الْعِلْمِ أَنْ يَقُولَ لِمَا لاَ يَعْلَمُ لاَ أَعْلَمُ‏.‏ فَإِنَّ اللَّهَ قَالَ لِنَبِيِّهِ صلى الله عليه وسلم ‏{‏قُلْ مَا أَسْأَلُكُمْ عَلَيْهِ مِنْ أَجْرٍ وَمَا أَنَا مِنَ الْمُتَكَلِّفِينَ‏}‏ وَإِنَّ قُرَيْشًا أَبْطَئُوا عَنِ الإِسْلاَمِ فَدَعَا عَلَيْهِمِ النَّبِيُّ صلى الله عليه وسلم فَقَالَ ‏\"‏ اللَّهُمَّ أَعِنِّي عَلَيْهِمْ بِسَبْعٍ كَسَبْعِ يُوسُفَ، فَأَخَذَتْهُمْ سَنَةٌ حَتَّى هَلَكُوا فِيهَا، وَأَكَلُوا الْمَيْتَةَ وَالْعِظَامَ وَيَرَى الرَّجُلُ مَا بَيْنَ السَّمَاءِ وَالأَرْضِ كَهَيْئَةِ الدُّخَانِ ‏\"‏، فَجَاءَهُ أَبُو سُفْيَانَ فَقَالَ يَا مُحَمَّدُ جِئْتَ تَأْمُرُنَا بِصِلَةِ الرَّحِمِ، وَإِنَّ قَوْمَكَ قَدْ هَلَكُوا فَادْعُ اللَّهَ، فَقَرَأَ ‏{‏فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ‏}‏ إِلَى قَوْلِهِ ‏{‏عَائِدُونَ‏}‏ أَفَيُكْشَفُ عَنْهُمْ عَذَابُ الآخِرَةِ إِذَا جَاءَ ثُمَّ عَادُوا إِلَى كُفْرِهِمْ فَذَلِكَ قَوْلُهُ تَعَالَى ‏{‏يَوْمَ نَبْطِشُ الْبَطْشَةَ الْكُبْرَى‏}‏ يَوْمَ بَدْرٍ وَلِزَامًا يَوْمَ بَدْرٍ ‏{‏الم * غُلِبَتِ الرُّومُ‏}‏ إِلَى ‏{‏سَيَغْلِبُونَ‏}‏ وَالرُّومُ قَدْ مَضَى‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4809","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4809","x":"Narrated Masruq:\n\nWe came upon `Abdullah bin Mas`ud and he said \"O people! If somebody knows something, he can say it, but if he does not know it, he should say, \"Allah knows better,' for it is a sign of having knowledge to say about something which one does not know, 'Allah knows better.' Allah said to His Prophet: 'Say (O Muhammad ! ) No wage do I ask of You for this (Qur'an) nor am I one of the pretenders (a person who pretends things which do not exist).' (38.86) Now I will tell you about Ad- Dukhan (the smoke), Allah's Messenger (ﷺ) invited the Quraish to embrace Islam, but they delayed their response. So he said, \"O Allah! Help me against them by sending on them seven years of famine similar to the seven years of famine of Joseph.\" So the famine year overtook them and everything was destroyed till they ate dead animals and skins. People started imagining to see smoke between them and the sky because of severe hunger. Allah said: 'Then watch you for the Day that the sky will bring forth a kind of smoke plainly visible, covering the people... This is painful torment.' (44.10-11) (So they invoked Allah) \"Our Lord! Remove the punishment from us really we are believers.\" How can there be an (effectual) reminder for them when an Apostle, explaining things clearly, has already come to them? Then they had turned away from him and said: 'One taught (by a human being), a madman?' 'We shall indeed remove punishment for a while, but truly, you will revert (to disbelief).' (44.12-15) Will the punishment be removed on the Day of Resurrection?\" `Abdullah added, \"The punishment was removed from them for a while but they reverted to disbelief, so Allah destroyed them on the Day of Badr. Allah said: 'The day We shall seize you with a mighty grasp. We will indeed (then) exact retribution.\" (44.16)","ar":"حَدَّثَنَا قُتَيْبَةُ، حَدَّثَنَا جَرِيرٌ، عَنِ الأَعْمَشِ، عَنْ أَبِي الضُّحَى، عَنْ مَسْرُوقٍ، قَالَ دَخَلْنَا عَلَى عَبْدِ اللَّهِ بْنِ مَسْعُودٍ، قَالَ يَا أَيُّهَا النَّاسُ مَنْ عَلِمَ شَيْئًا فَلْيَقُلْ بِهِ، وَمَنْ لَمْ يَعْلَمْ فَلْيَقُلِ اللَّهُ أَعْلَمُ، فَإِنَّ مِنَ الْعِلْمِ أَنْ يَقُولَ لِمَا لاَ يَعْلَمُ اللَّهُ أَعْلَمُ، قَالَ اللَّهُ عَزَّ وَجَلَّ لِنَبِيِّهِ صلى الله عليه وسلم ‏{‏قُلْ مَا أَسْأَلُكُمْ عَلَيْهِ مِنْ أَجْرٍ وَمَا أَنَا مِنَ الْمُتَكَلِّفِينَ‏}‏ وَسَأُحَدِّثُكُمْ عَنِ الدُّخَانِ إِنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم دَعَا قُرَيْشًا إِلَى الإِسْلاَمِ فَأَبْطَئُوا عَلَيْهِ فَقَالَ ‏\"‏ اللَّهُمَّ أَعِنِّي عَلَيْهِمْ بِسَبْعٍ كَسَبْعِ يُوسُفَ ‏\"‏، فَأَخَذَتْهُمْ سَنَةٌ فَحَصَّتْ كُلَّ شَىْءٍ حَتَّى أَكَلُوا الْمَيْتَةَ وَالْجُلُودَ حَتَّى جَعَلَ الرَّجُلُ يَرَى بَيْنَهُ وَبَيْنَ السَّمَاءِ دُخَانًا مِنَ الْجُوعِ، قَالَ اللَّهُ عَزَّ وَجَلَّ ‏{‏فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ * يَغْشَى النَّاسَ هَذَا عَذَابٌ أَلِيمٌ‏}‏ قَالَ فَدَعَوْا ‏{‏رَبَّنَا اكْشِفْ عَنَّا الْعَذَابَ إِنَّا مُؤْمِنُونَ * أَنَّى لَهُمُ الذِّكْرَى وَقَدْ جَاءَهُمْ رَسُولٌ مُبِينٌ * ثُمَّ تَوَلَّوْا عَنْهُ وَقَالُوا مُعَلَّمٌ مَجْنُونٌ * إِنَّا كَاشِفُو الْعَذَابِ قَلِيلاً إِنَّكُمْ عَائِدُونَ‏}‏ أَفَيُكْشَفُ الْعَذَابُ يَوْمَ الْقِيَامَةِ قَالَ فَكُشِفَ ثُمَّ عَادُوا فِي كُفْرِهِمْ، فَأَخَذَهُمُ اللَّهُ يَوْمَ بَدْرٍ قَالَ اللَّهُ تَعَالَى ‏{‏يَوْمَ نَبْطِشُ الْبَطْشَةَ الْكُبْرَى إِنَّا مُنْتَقِمُونَ‏}‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4821","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4821","x":"Narrated `Abdullah:\n\nIt (i.e., the imagined smoke) was because, when the Quraish refused to obey the Prophet, he asked Allah to afflict them with years of famine similar to those of (Prophet) Joseph. So they were stricken with famine and fatigue, so much so that they ate even bones. A man would look towards the sky and imagine seeing something like smoke between him and the sky because of extreme fatigue. So Allah revealed:-- 'Then watch you for the Day that the sky will bring forth a kind of smoke plainly visible, covering the people; this is a painfull of torment.' (44.10-11) Then someone (Abu Sufyan) came to Allah's Messenger (ﷺ) and said, \"O Allah's Messenger (ﷺ)! Invoke Allah to send rain for the tribes of Mudar for they are on the verge of destruction.\" On that the Prophet (ﷺ) said (astonishingly) \"Shall I invoke Allah) for the tribes of Mudar? Verily, you are a brave man!\" But the Prophet prayed for rain and it rained for them. Then the Verse was revealed. 'But truly you will return (to disbelief).' (44.15) (When the famine was over and) they restored prosperity and welfare, they reverted to their ways (of heathenism) whereupon Allah revealed: 'On the Day when We shall seize you with a Mighty Grasp. We will indeed (then) exact retribution.' (44.16) The narrator said, \"That was the day of the Battle of Badr.\"","ar":"حَدَّثَنَا يَحْيَى، حَدَّثَنَا أَبُو مُعَاوِيَةَ، عَنِ الأَعْمَشِ، عَنْ مُسْلِمٍ، عَنْ مَسْرُوقٍ، قَالَ قَالَ عَبْدُ اللَّهِ إِنَّمَا كَانَ هَذَا لأَنَّ قُرَيْشًا لَمَّا اسْتَعْصَوْا عَلَى النَّبِيِّ صلى الله عليه وسلم دَعَا عَلَيْهِمْ بِسِنِينَ كَسِنِي يُوسُفَ، فَأَصَابَهُمْ قَحْطٌ وَجَهْدٌ حَتَّى أَكَلُوا الْعِظَامَ، فَجَعَلَ الرَّجُلُ يَنْظُرُ إِلَى السَّمَاءِ فَيَرَى مَا بَيْنَهُ وَبَيْنَهَا كَهَيْئَةِ الدُّخَانِ مِنَ الْجَهْدِ، فَأَنْزَلَ اللَّهُ تَعَالَى ‏{‏فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ * يَغْشَى النَّاسَ هَذَا عَذَابٌ أَلِيمٌ‏}‏ قَالَ فَأُتِيَ رَسُولُ اللَّهِ صلى الله عليه وسلم فَقِيلَ يَا رَسُولَ اللَّهِ اسْتَسْقِ اللَّهَ لِمُضَرَ، فَإِنَّهَا قَدْ هَلَكَتْ‏.‏ قَالَ ‏\"‏ لِمُضَرَ إِنَّكَ لَجَرِيءٌ ‏\"‏‏.‏ فَاسْتَسْقَى فَسُقُوا‏.‏ فَنَزَلَتْ ‏{‏إِنَّكُمْ عَائِدُونَ‏}‏ فَلَمَّا أَصَابَتْهُمُ الرَّفَاهِيَةُ عَادُوا إِلَى حَالِهِمْ حِينَ أَصَابَتْهُمُ الرَّفَاهِيَةُ‏.‏ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏{‏يَوْمَ نَبْطِشُ الْبَطْشَةَ الْكُبْرَى إِنَّا مُنْتَقِمُونَ‏}‏ قَالَ يَعْنِي يَوْمَ بَدْرٍ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4823","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4823","x":"Narrated Masruq:\n\nI came upon `Abdullah and he said, \"When Allah's Messenger (ﷺ) invited Quraish (to Islam), they disbelieved him and stood against him. So he (the Prophet) said, \"O Allah! Help me against them by afflicting them with seven years of famine similar to the seven years of Joseph.' So they were stricken with a year of drought that destroyed everything, and they started eating dead animals, and if one of them got up he would see something like smoke between him and the sky from the severe fatigue and hunger.\" `Abdullah then recited:-- 'Then watch you for the Day that the sky will bring forth a kind of smoke plainly visible, covering the people. This is a painful torment... (till he reached)........ We shall indeed remove the punishment for a while, but truly you will revert (to heathenism): (44.10-15) `Abdullah added: \"Will the punishment be removed from them on the Day of Resurrection?\" He added,\" The severe grasp\" was the Day of the Battle of Badr.\"","ar":"حَدَّثَنَا سُلَيْمَانُ بْنُ حَرْبٍ، حَدَّثَنَا جَرِيرُ بْنُ حَازِمٍ، عَنِ الأَعْمَشِ، عَنْ أَبِي الضُّحَى، عَنْ مَسْرُوقٍ، قَالَ دَخَلْتُ عَلَى عَبْدِ اللَّهِ ثُمَّ قَالَ إِنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم لَمَّا دَعَا قُرَيْشًا كَذَّبُوهُ وَاسْتَعْصَوْا عَلَيْهِ فَقَالَ ‏\"‏ اللَّهُمَّ أَعِنِّي عَلَيْهِمْ بِسَبْعٍ كَسَبْعِ يُوسُفَ ‏\"‏‏.‏ فَأَصَابَتْهُمْ سَنَةٌ حَصَّتْ ـ يَعْنِي ـ كُلَّ شَىْءٍ حَتَّى كَانُوا يَأْكُلُونَ الْمَيْتَةَ فَكَانَ يَقُومُ أَحَدُهُمْ فَكَانَ يَرَى بَيْنَهُ وَبَيْنَ السَّمَاءِ مِثْلَ الدُّخَانِ مِنَ الْجَهْدِ وَالْجُوعِ ثُمَّ قَرَأَ ‏{‏فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ * يَغْشَى النَّاسَ هَذَا عَذَابٌ أَلِيمٌ‏}‏ حَتَّى بَلَغَ ‏{‏إِنَّا كَاشِفُو الْعَذَابِ قَلِيلاً إِنَّكُمْ عَائِدُونَ‏}‏ قَالَ عَبْدُ اللَّهِ أَفَيُكْشَفُ عَنْهُمُ الْعَذَابُ يَوْمَ الْقِيَامَةِ قَالَ وَالْبَطْشَةُ الْكُبْرَى يَوْمَ بَدْرٍ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 2798b","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-2798b","x":"Masruq reported that there came to Abdullah a person and said:\n\nI have left behind in the mosque a man who explains the Qur'an according to his personal discretion and he explained this verse:\" So wait for the day when the Heaven brings a clear smoke.\" He says that a smoke would come to the people on the Day of Resurrection anl it will withhold breath and they would be inflicted with cold. 'Abdullah said: He who has knowledge should say something and he who has no knowledge should simply say: Allah is best aware. This reflects the understanding of a person that he should say about that which he does not know that it is Allah who knows best. The fact is that when the Quraish disobeyed Allah's Apostle (ﷺ) he supplicated Allah that they should be afflicted with famine and starvation as was done in case of Yusuf. And they were so much hard pressed that a person would ace the sky and he would see between him and the sky something like smoke and they were so much hard pressed that they began to cat the bones, and a person came to Allah's Apostle (ﷺ) and said: Allah's Messenger. seek forgiveness for the tribe of Mudar for (its people) have been undone. The Messenger (ﷺ) said: For Mudar? You are overbold, but he supplicated Allah for them. It was upon this that this verse was revealed:\" We shall remove the chastisement a little, but they will surely return to evil\" (xliv. 15). lie (the narrator) said: There was a downpoor of rain upon them. When there was some relief for them they returned to the same position as they had been before, and Allah, the Exalted and Glorious, revealed this verse:\" So wait for the day when the heaven brings a clear smoke enveloping people. This is a grievous torment on the day when We seize them with the most violent seizing; surely, We shall exact retribution.\" And this (seizing) implied (Battle) of Badr.","ar":"حَدَّثَنَا أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا أَبُو مُعَاوِيَةَ، وَوَكِيعٌ، ح وَحَدَّثَنِي أَبُو سَعِيدٍ، الأَشَجُّ أَخْبَرَنَا وَكِيعٌ، ح وَحَدَّثَنَا عُثْمَانُ بْنُ أَبِي شَيْبَةَ، حَدَّثَنَا جَرِيرٌ، كُلُّهُمْ عَنِ الأَعْمَشِ، ح وَحَدَّثَنَا يَحْيَى بْنُ يَحْيَى، وَأَبُو كُرَيْبٍ - وَاللَّفْظُ لِيَحْيَى - قَالاَ حَدَّثَنَا أَبُو مُعَاوِيَةَ، عَنِ الأَعْمَشِ، عَنْ مُسْلِمِ بْنِ صُبَيْحٍ، عَنْ مَسْرُوقٍ، قَالَ جَاءَ إِلَى عَبْدِ اللَّهِ رَجُلٌ فَقَالَ تَرَكْتُ فِي الْمَسْجِدِ رَجُلاً يُفَسِّرُ الْقُرْآنَ بِرَأْيِهِ يُفَسِّرُ هَذِهِ الآيَةَ ‏{‏ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ‏}‏ قَالَ يَأْتِي النَّاسَ يَوْمَ الْقِيَامَةِ دُخَانٌ فَيَأْخُذُ بِأَنْفَاسِهِمْ حَتَّى يَأْخُذَهُمْ مِنْهُ كَهَيْئَةِ الزُّكَامِ ‏.‏ فَقَالَ عَبْدُ اللَّهِ مَنْ عَلِمَ عِلْمًا فَلْيَقُلْ بِهِ وَمَنْ لَمْ يَعْلَمْ فَلْيَقُلِ اللَّهُ أَعْلَمُ فَإِنَّ مِنْ فِقْهِ الرَّجُلِ أَنْ يَقُولَ لِمَا لاَ عِلْمَ لَهُ بِهِ اللَّهُ أَعْلَمُ ‏.‏ إِنَّمَا كَانَ هَذَا أَنَّ قُرَيْشًا لَمَّا اسْتَعْصَتْ عَلَى النَّبِيِّ صلى الله عليه وسلم دَعَا عَلَيْهِمْ بِسِنِينَ كَسِنِي يُوسُفَ فَأَصَابَهُمْ قَحْطٌ وَجَهْدٌ حَتَّى جَعَلَ الرَّجُلُ يَنْظُرُ إِلَى السَّمَاءِ فَيَرَى بَيْنَهُ وَبَيْنَهَا كَهَيْئَةِ الدُّخَانِ مِنَ الْجَهْدِ وَحَتَّى أَكَلُوا الْعِظَامَ فَأَتَى النَّبِيَّ صلى الله عليه وسلم رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ اسْتَغْفِرِ اللَّهَ لِمُضَرَ فَإِنَّهُمْ قَدْ هَلَكُوا فَقَالَ ‏\"‏ لِمُضَرَ إِنَّكَ لَجَرِيءٌ ‏\"‏ ‏.‏ قَالَ فَدَعَا اللَّهَ لَهُمْ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏{‏ إِنَّا كَاشِفُو الْعَذَابِ قَلِيلاً إِنَّكُمْ عَائِدُونَ‏}‏ قَالَ فَمُطِرُوا فَلَمَّا أَصَابَتْهُمُ الرَّفَاهِيَةُ - قَالَ - عَادُوا إِلَى مَا كَانُوا عَلَيْهِ - قَالَ - فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏{‏ فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ * يَغْشَى النَّاسَ هَذَا عَذَابٌ أَلِيمٌ‏}‏ ‏{‏ يَوْمَ نَبْطِشُ الْبَطْشَةَ الْكُبْرَى إِنَّا مُنْتَقِمُونَ‏}‏ قَالَ يَعْنِي يَوْمَ بَدْرٍ ‏.‏","v":[]}],"16":[{"c":"Sahih Bukhari","r":"Hadith 1007","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-1007","x":"Narrated Masruq:\n\nWe were with `Abdullah and he said, \"When the Prophet (ﷺ) saw the refusal of the people to accept Islam he said, \"O Allah! Send (famine) years on them for (seven years) like the seven years (of famine during the time) of (Prophet) Joseph.\" So famine overtook them for one year and destroyed every kind of life to such an extent that the people started eating hides, carcasses and rotten dead animals. Whenever one of them looked towards the sky, he would (imagine himself to) see smoke because of hunger. So Abu Sufyan went to the Prophet (ﷺ) and said, \"O Muhammad! You order people to obey Allah and to keep good relations with kith and kin. No doubt the people of your tribe are dying, so please pray to Allah for them.\" So Allah revealed: \"Then watch you For the day that The sky will bring forth a kind Of smoke Plainly visible... Verily! You will return (to disbelief) On the day when We shall seize You with a mighty grasp. (44.10-16) Ibn Mas`ud added, \"Al-Batsha (i.e. grasp) happened in the battle of Badr and no doubt smoke, Al-Batsha, Al-Lizam, and the verse of Surat Ar-Rum have all passed.","ar":"حَدَّثَنَا عُثْمَانُ بْنُ أَبِي شَيْبَةَ، قَالَ حَدَّثَنَا جَرِيرٌ، عَنْ مَنْصُورٍ، عَنْ أَبِي الضُّحَى، عَنْ مَسْرُوقٍ، قَالَ كُنَّا عِنْدَ عَبْدِ اللَّهِ فَقَالَ إِنَّ النَّبِيَّ صلى الله عليه وسلم لَمَّا رَأَى مِنَ النَّاسِ إِدْبَارًا قَالَ ‏\"‏ اللَّهُمَّ سَبْعٌ كَسَبْعِ يُوسُفَ ‏\"‏‏.‏ فَأَخَذَتْهُمْ سَنَةٌ حَصَّتْ كُلَّ شَىْءٍ حَتَّى أَكَلُوا الْجُلُودَ وَالْمَيْتَةَ وَالْجِيَفَ، وَيَنْظُرَ أَحَدُهُمْ إِلَى السَّمَاءِ فَيَرَى الدُّخَانَ مِنَ الْجُوعِ، فَأَتَاهُ أَبُو سُفْيَانَ فَقَالَ يَا مُحَمَّدُ إِنَّكَ تَأْمُرُ بِطَاعَةِ اللَّهِ وَبِصِلَةِ الرَّحِمِ وَإِنَّ قَوْمَكَ قَدْ هَلَكُوا، فَادْعُ اللَّهَ لَهُمْ قَالَ اللَّهُ تَعَالَى ‏{‏فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ‏}‏ إِلَى قَوْلِهِ ‏{‏عَائِدُونَ * يَوْمَ نَبْطِشُ الْبَطْشَةَ الْكُبْرَى‏}‏ فَالْبَطْشَةُ يَوْمَ بَدْرٍ، وَقَدْ مَضَتِ الدُّخَانُ وَالْبَطْشَةُ وَاللِّزَامُ وَآيَةُ الرُّومِ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 1020","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-1020","x":"Narrated Masruq:\n\nOne day I went to Ibn Mas`ud who said, \"When Quraish delayed in embracing Islam, the Prophet (ﷺ) I invoked Allah to curse them, so they were afflicted with a (famine) year because of which many of them died and they ate the carcasses and Abu Sufyan came to the Prophet (ﷺ) and said, 'O Muhammad! You came to order people to keep good relation with kith and kin and your nation is being destroyed, so invoke Allah I ? So the Prophet (ﷺ) I recited the Holy verses of Sirat-Ad-Dukhan: 'Then watch you For the day that The sky will Bring forth a kind Of smoke Plainly visible.' (44.10) When the famine was taken off, the people renegade once again as nonbelievers. The statement of Allah, (in Sura \"Ad- Dukhan\"-44) refers to that: 'On the day when We shall seize You with a mighty grasp.' (44.16) And that was what happened on the day of the battle of Badr.\" Asbath added on the authority of Mansur, \"Allah's Messenger (ﷺ) prayed for them and it rained heavily for seven days. So the people complained of the excessive rain. The Prophet (ﷺ) said, 'O Allah! (Let it rain) around us and not on us.' So the clouds dispersed over his head and it rained over the surroundings.\"","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ كَثِيرٍ، عَنْ سُفْيَانَ، حَدَّثَنَا مَنْصُورٌ، وَالأَعْمَشُ، عَنْ أَبِي الضُّحَى، عَنْ مَسْرُوقٍ، قَالَ أَتَيْتُ ابْنَ مَسْعُودٍ فَقَالَ إِنَّ قُرَيْشًا أَبْطَئُوا عَنِ الإِسْلاَمِ،، فَدَعَا عَلَيْهِمُ النَّبِيُّ صلى الله عليه وسلم فَأَخَذَتْهُمْ سَنَةٌ حَتَّى هَلَكُوا فِيهَا وَأَكَلُوا الْمَيْتَةَ وَالْعِظَامَ، فَجَاءَهُ أَبُو سُفْيَانَ فَقَالَ يَا مُحَمَّدُ، جِئْتَ تَأْمُرُ بِصِلَةِ الرَّحِمِ، وَإِنَّ قَوْمَكَ هَلَكُوا، فَادْعُ اللَّهَ‏.‏ فَقَرَأَ ‏{‏فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ‏}‏ ثُمَّ عَادُوا إِلَى كُفْرِهِمْ فَذَلِكَ قَوْلُهُ تَعَالَى ‏{‏يَوْمَ نَبْطِشُ الْبَطْشَةَ الْكُبْرَى‏}‏ يَوْمَ بَدْرٍ‏.‏ قَالَ وَزَادَ أَسْبَاطٌ عَنْ مَنْصُورٍ فَدَعَا رَسُولُ اللَّهِ صلى الله عليه وسلم، فَسُقُوا الْغَيْثَ، فَأَطْبَقَتْ عَلَيْهِمْ سَبْعًا، وَشَكَا النَّاسُ كَثْرَةَ الْمَطَرِ فَقَالَ ‏\"‏ اللَّهُمَّ حَوَالَيْنَا وَلاَ عَلَيْنَا ‏\"‏‏.‏ فَانْحَدَرَتِ السَّحَابَةُ عَنْ رَأْسِهِ، فَسُقُوا النَّاسُ حَوْلَهُمْ‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4774","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4774","x":"Narrated Masruq:\n\nWhile a man was delivering a speech in the tribe of Kinda, he said, \"Smoke will prevail on the Day of Resurrection and will deprive the hypocrites their faculties of hearing and seeing. The believers will be afflicted with something like cold only thereof.\" That news scared us, so I went to (Abdullah) Ibn Mas`ud while he was reclining (and told him the story) whereupon he became angry, sat up and said, \"He who knows a thing can say, it, but if he does not know, he should say, 'Allah knows best,' for it is an aspect of knowledge to say, 'I do not know,' if you do not know a certain thing. Allah said to His prophet. 'Say (O Muhammad): No wage do I ask of you for this (Qur'an), nor I am one of the pretenders (a person who pretends things which do not exist.)' (38.86) The Qur'aish delayed in embracing Islam for a period, so the Prophet (ﷺ) invoked evil on them, saying, 'O Allah! Help me against them by sending seven years of (famine) like those of Joseph.' So they were afflicted with such a severe year of famine that they were destroyed therein and ate dead animals and bones. They started seeing something like smoke between the sky and the earth (because of severe hunger). Abu Sufyan then came (to the Prophet) and said, \"O Muhammad! You came to order us for to keep good relations with Kith and kin, and your kinsmen have now perished, so please invoke Allah (to relieve them).' Then Ibn Mas`ud recited:-- 'Then watch you for the day that the sky will bring forth a kind of smoke plainly visible....but truly you will return! (to disbelief) (44.10-15) Ibn Mas`ud added, Then the punishment was stopped, but truly, they reverted to heathenism (their old way). So Allah (threatened them thus): 'On the day when we shall seize you with a mighty grasp.' (44.16) And that was the day of the Battle of Badr. Allah's saying- \"Lizama\" (the punishment) refers to the day of Badr Allah's Statement: Alif-Lam-Mim, the Romans have been defeated, and they, after their defeat, will be victorious,' (30.1- 3) (This verse): Indicates that the defeat of Byzantine has already passed.","ar":"حَدَّثَنَا مُحَمَّدُ بْنُ كَثِيرٍ، حَدَّثَنَا سُفْيَانُ، حَدَّثَنَا مَنْصُورٌ، وَالأَعْمَشُ، عَنْ أَبِي الضُّحَى، عَنْ مَسْرُوقٍ، قَالَ بَيْنَمَا رَجُلٌ يُحَدِّثُ فِي كِنْدَةَ فَقَالَ يَجِيءُ دُخَانٌ يَوْمَ الْقِيَامَةِ فَيَأْخُذُ بِأَسْمَاعِ الْمُنَافِقِينَ وَأَبْصَارِهِمْ، يَأْخُذُ الْمُؤْمِنَ كَهَيْئَةِ الزُّكَامِ‏.‏ فَفَزِعْنَا، فَأَتَيْتُ ابْنَ مَسْعُودٍ، وَكَانَ مُتَّكِئًا، فَغَضِبَ فَجَلَسَ فَقَالَ مَنْ عَلِمَ فَلْيَقُلْ، وَمَنْ لَمْ يَعْلَمْ فَلْيَقُلِ اللَّهُ أَعْلَمُ‏.‏ فَإِنَّ مِنَ الْعِلْمِ أَنْ يَقُولَ لِمَا لاَ يَعْلَمُ لاَ أَعْلَمُ‏.‏ فَإِنَّ اللَّهَ قَالَ لِنَبِيِّهِ صلى الله عليه وسلم ‏{‏قُلْ مَا أَسْأَلُكُمْ عَلَيْهِ مِنْ أَجْرٍ وَمَا أَنَا مِنَ الْمُتَكَلِّفِينَ‏}‏ وَإِنَّ قُرَيْشًا أَبْطَئُوا عَنِ الإِسْلاَمِ فَدَعَا عَلَيْهِمِ النَّبِيُّ صلى الله عليه وسلم فَقَالَ ‏\"‏ اللَّهُمَّ أَعِنِّي عَلَيْهِمْ بِسَبْعٍ كَسَبْعِ يُوسُفَ، فَأَخَذَتْهُمْ سَنَةٌ حَتَّى هَلَكُوا فِيهَا، وَأَكَلُوا الْمَيْتَةَ وَالْعِظَامَ وَيَرَى الرَّجُلُ مَا بَيْنَ السَّمَاءِ وَالأَرْضِ كَهَيْئَةِ الدُّخَانِ ‏\"‏، فَجَاءَهُ أَبُو سُفْيَانَ فَقَالَ يَا مُحَمَّدُ جِئْتَ تَأْمُرُنَا بِصِلَةِ الرَّحِمِ، وَإِنَّ قَوْمَكَ قَدْ هَلَكُوا فَادْعُ اللَّهَ، فَقَرَأَ ‏{‏فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ‏}‏ إِلَى قَوْلِهِ ‏{‏عَائِدُونَ‏}‏ أَفَيُكْشَفُ عَنْهُمْ عَذَابُ الآخِرَةِ إِذَا جَاءَ ثُمَّ عَادُوا إِلَى كُفْرِهِمْ فَذَلِكَ قَوْلُهُ تَعَالَى ‏{‏يَوْمَ نَبْطِشُ الْبَطْشَةَ الْكُبْرَى‏}‏ يَوْمَ بَدْرٍ وَلِزَامًا يَوْمَ بَدْرٍ ‏{‏الم * غُلِبَتِ الرُّومُ‏}‏ إِلَى ‏{‏سَيَغْلِبُونَ‏}‏ وَالرُّومُ قَدْ مَضَى‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4809","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4809","x":"Narrated Masruq:\n\nWe came upon `Abdullah bin Mas`ud and he said \"O people! If somebody knows something, he can say it, but if he does not know it, he should say, \"Allah knows better,' for it is a sign of having knowledge to say about something which one does not know, 'Allah knows better.' Allah said to His Prophet: 'Say (O Muhammad ! ) No wage do I ask of You for this (Qur'an) nor am I one of the pretenders (a person who pretends things which do not exist).' (38.86) Now I will tell you about Ad- Dukhan (the smoke), Allah's Messenger (ﷺ) invited the Quraish to embrace Islam, but they delayed their response. So he said, \"O Allah! Help me against them by sending on them seven years of famine similar to the seven years of famine of Joseph.\" So the famine year overtook them and everything was destroyed till they ate dead animals and skins. People started imagining to see smoke between them and the sky because of severe hunger. Allah said: 'Then watch you for the Day that the sky will bring forth a kind of smoke plainly visible, covering the people... This is painful torment.' (44.10-11) (So they invoked Allah) \"Our Lord! Remove the punishment from us really we are believers.\" How can there be an (effectual) reminder for them when an Apostle, explaining things clearly, has already come to them? Then they had turned away from him and said: 'One taught (by a human being), a madman?' 'We shall indeed remove punishment for a while, but truly, you will revert (to disbelief).' (44.12-15) Will the punishment be removed on the Day of Resurrection?\" `Abdullah added, \"The punishment was removed from them for a while but they reverted to disbelief, so Allah destroyed them on the Day of Badr. Allah said: 'The day We shall seize you with a mighty grasp. We will indeed (then) exact retribution.\" (44.16)","ar":"حَدَّثَنَا قُتَيْبَةُ، حَدَّثَنَا جَرِيرٌ، عَنِ الأَعْمَشِ، عَنْ أَبِي الضُّحَى، عَنْ مَسْرُوقٍ، قَالَ دَخَلْنَا عَلَى عَبْدِ اللَّهِ بْنِ مَسْعُودٍ، قَالَ يَا أَيُّهَا النَّاسُ مَنْ عَلِمَ شَيْئًا فَلْيَقُلْ بِهِ، وَمَنْ لَمْ يَعْلَمْ فَلْيَقُلِ اللَّهُ أَعْلَمُ، فَإِنَّ مِنَ الْعِلْمِ أَنْ يَقُولَ لِمَا لاَ يَعْلَمُ اللَّهُ أَعْلَمُ، قَالَ اللَّهُ عَزَّ وَجَلَّ لِنَبِيِّهِ صلى الله عليه وسلم ‏{‏قُلْ مَا أَسْأَلُكُمْ عَلَيْهِ مِنْ أَجْرٍ وَمَا أَنَا مِنَ الْمُتَكَلِّفِينَ‏}‏ وَسَأُحَدِّثُكُمْ عَنِ الدُّخَانِ إِنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم دَعَا قُرَيْشًا إِلَى الإِسْلاَمِ فَأَبْطَئُوا عَلَيْهِ فَقَالَ ‏\"‏ اللَّهُمَّ أَعِنِّي عَلَيْهِمْ بِسَبْعٍ كَسَبْعِ يُوسُفَ ‏\"‏، فَأَخَذَتْهُمْ سَنَةٌ فَحَصَّتْ كُلَّ شَىْءٍ حَتَّى أَكَلُوا الْمَيْتَةَ وَالْجُلُودَ حَتَّى جَعَلَ الرَّجُلُ يَرَى بَيْنَهُ وَبَيْنَ السَّمَاءِ دُخَانًا مِنَ الْجُوعِ، قَالَ اللَّهُ عَزَّ وَجَلَّ ‏{‏فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ * يَغْشَى النَّاسَ هَذَا عَذَابٌ أَلِيمٌ‏}‏ قَالَ فَدَعَوْا ‏{‏رَبَّنَا اكْشِفْ عَنَّا الْعَذَابَ إِنَّا مُؤْمِنُونَ * أَنَّى لَهُمُ الذِّكْرَى وَقَدْ جَاءَهُمْ رَسُولٌ مُبِينٌ * ثُمَّ تَوَلَّوْا عَنْهُ وَقَالُوا مُعَلَّمٌ مَجْنُونٌ * إِنَّا كَاشِفُو الْعَذَابِ قَلِيلاً إِنَّكُمْ عَائِدُونَ‏}‏ أَفَيُكْشَفُ الْعَذَابُ يَوْمَ الْقِيَامَةِ قَالَ فَكُشِفَ ثُمَّ عَادُوا فِي كُفْرِهِمْ، فَأَخَذَهُمُ اللَّهُ يَوْمَ بَدْرٍ قَالَ اللَّهُ تَعَالَى ‏{‏يَوْمَ نَبْطِشُ الْبَطْشَةَ الْكُبْرَى إِنَّا مُنْتَقِمُونَ‏}‏‏.‏","v":[]},{"c":"Sahih Bukhari","r":"Hadith 4821","u":"https://quranx.com/Hadith/Bukhari/DarusSalam/Hadith-4821","x":"Narrated `Abdullah:\n\nIt (i.e., the imagined smoke) was because, when the Quraish refused to obey the Prophet, he asked Allah to afflict them with years of famine similar to those of (Prophet) Joseph. So they were stricken with famine and fatigue, so much so that they ate even bones. A man would look towards the sky and imagine seeing something like smoke between him and the sky because of extreme fatigue. So Allah revealed:-- 'Then watch you for the Day that the sky will bring forth a kind of smoke plainly visible, covering the people; this is a painfull of torment.' (44.10-11) Then someone (Abu Sufyan) came to Allah's Messenger (ﷺ) and said, \"O Allah's Messenger (ﷺ)! Invoke Allah to send rain for the tribes of Mudar for they are on the verge of destruction.\" On that the Prophet (ﷺ) said (astonishingly) \"Shall I invoke Allah) for the tribes of Mudar? Verily, you are a brave man!\" But the Prophet prayed for rain and it rained for them. Then the Verse was revealed. 'But truly you will return (to disbelief).' (44.15) (When the famine was over and) they restored prosperity and welfare, they reverted to their ways (of heathenism) whereupon Allah revealed: 'On the Day when We shall seize you with a Mighty Grasp. We will indeed (then) exact retribution.' (44.16) The narrator said, \"That was the day of the Battle of Badr.\"","ar":"حَدَّثَنَا يَحْيَى، حَدَّثَنَا أَبُو مُعَاوِيَةَ، عَنِ الأَعْمَشِ، عَنْ مُسْلِمٍ، عَنْ مَسْرُوقٍ، قَالَ قَالَ عَبْدُ اللَّهِ إِنَّمَا كَانَ هَذَا لأَنَّ قُرَيْشًا لَمَّا اسْتَعْصَوْا عَلَى النَّبِيِّ صلى الله عليه وسلم دَعَا عَلَيْهِمْ بِسِنِينَ كَسِنِي يُوسُفَ، فَأَصَابَهُمْ قَحْطٌ وَجَهْدٌ حَتَّى أَكَلُوا الْعِظَامَ، فَجَعَلَ الرَّجُلُ يَنْظُرُ إِلَى السَّمَاءِ فَيَرَى مَا بَيْنَهُ وَبَيْنَهَا كَهَيْئَةِ الدُّخَانِ مِنَ الْجَهْدِ، فَأَنْزَلَ اللَّهُ تَعَالَى ‏{‏فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ * يَغْشَى النَّاسَ هَذَا عَذَابٌ أَلِيمٌ‏}‏ قَالَ فَأُتِيَ رَسُولُ اللَّهِ صلى الله عليه وسلم فَقِيلَ يَا رَسُولَ اللَّهِ اسْتَسْقِ اللَّهَ لِمُضَرَ، فَإِنَّهَا قَدْ هَلَكَتْ‏.‏ قَالَ ‏\"‏ لِمُضَرَ إِنَّكَ لَجَرِيءٌ ‏\"‏‏.‏ فَاسْتَسْقَى فَسُقُوا‏.‏ فَنَزَلَتْ ‏{‏إِنَّكُمْ عَائِدُونَ‏}‏ فَلَمَّا أَصَابَتْهُمُ الرَّفَاهِيَةُ عَادُوا إِلَى حَالِهِمْ حِينَ أَصَابَتْهُمُ الرَّفَاهِيَةُ‏.‏ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏{‏يَوْمَ نَبْطِشُ الْبَطْشَةَ الْكُبْرَى إِنَّا مُنْتَقِمُونَ‏}‏ قَالَ يَعْنِي يَوْمَ بَدْرٍ‏.‏","v":[]},{"c":"Sahih Muslim","r":"Hadith 2798a","u":"https://quranx.com/Hadith/Muslim/Reference/Hadith-2798a","x":"Masruq reported:\n\nWe were sitting in the company of Abdullah and he was lying on the bed that a person came and said: Abd Abd al-Rabmin, a story-teller at the gates of Kinda says that the verse (of the Qur'an) which deals with the\" smoke\" implies that which is about to come and it would hold the breath of the infidels and would inflict the believers with cold. Thereupon Abdullah got up and said in anger. O people, fear Allah and say only that which one knows amongst you and do not say which he does not know and he should simply say: Allah has the best knowledge for He has the best knowledge amongst all of you. It does not behove him to say that which he does not know. Allah has the best knowledge of it. Verily Allah, the Exalted and Glorious, said to His Prophet (ﷺ) to state:\" I do not ask from you any remuneration and I am not the one to put you in trouble,\" and when Allah's Mesqenger (ﷺ) saw people turning back (from religion) he said: O Allah, afflict thern with seven famines as was done in the case of Yusuf, so they were afflicted with famine by which they were forced to eat everything until they were obliged to eat the hides and the dead bodies because of hunger, and every one of them looked towards the sky and he found a smoke. And Abu Sufyan came and he said: Muhammad, you have come to command us to obey Allah and cement the ties of blood- relation whereas your people are undone; supplicate Allah for tlicm. Thereupon Allah, the Exalted and Glorious, said:\" Wait for the day when there would be clear smoke from the sky which would envelop people and that would be grievous torivent\" up to the words:\" you are going to return to (evil).\" (if this verse implied the torment of the next life) could the chastisement of the next (life) be averted (as the Qur'an states): On the day when We seize (them) with the most violent seizing; surely We shall exact retribution\" (xliv. 16)? The seizing (in the hadith) implies that of the Day of Badr. And so far as the sign of smoke, seizing, inevitability and signs of Rome are concern- ed, they have become things of the past now.","ar":"أَخْبَرَنَا إِسْحَاقُ بْنُ إِبْرَاهِيمَ، أَخْبَرَنَا جَرِيرٌ، عَنْ مَنْصُورٍ، عَنْ أَبِي الضُّحَى، عَنْ مَسْرُوقٍ، قَالَ كُنَّا عِنْدَ عَبْدِ اللَّهِ جُلُوسًا وَهُوَ مُضْطَجِعٌ بَيْنَنَا فَأَتَاهُ رَجُلٌ فَقَالَ يَا أَبَا عَبْدِ الرَّحْمَنِ إِنَّ قَاصًّا عِنْدَ أَبْوَابِ كِنْدَةَ يَقُصُّ وَيَزْعُمُ أَنَّ آيَةَ الدُّخَانِ تَجِيءُ فَتَأْخُذُ بِأَنْفَاسِ الْكُفَّارِ وَيَأْخُذُ الْمُؤْمِنِينَ مِنْهُ كَهَيْئَةِ الزُّكَامِ فَقَالَ عَبْدُ اللَّهِ وَجَلَسَ وَهُوَ غَضْبَانُ يَا أَيُّهَا النَّاسُ اتَّقُوا اللَّهَ مَنْ عَلِمَ مِنْكُمْ شَيْئًا فَلْيَقُلْ بِمَا يَعْلَمُ وَمَنْ لَمْ يَعْلَمْ فَلْيَقُلِ اللَّهُ أَعْلَمُ فَإِنَّهُ أَعْلَمُ لأَحَدِكُمْ أَنْ يَقُولَ لِمَا لاَ يَعْلَمُ اللَّهُ أَعْلَمُ فَإِنَّ اللَّهَ عَزَّ وَجَلَّ قَالَ لِنَبِيِّهِ صلى الله عليه وسلم ‏{‏ قُلْ مَا أَسْأَلُكُمْ عَلَيْهِ مِنْ أَجْرٍ وَمَا أَنَا مِنَ الْمُتَكَلِّفِينَ‏}‏ إِنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم لَمَّا رَأَى مِنَ النَّاسِ إِدْبَارًا فَقَالَ ‏\"‏ اللَّهُمَّ سَبْعٌ كَسَبْعِ يُوسُفَ ‏\"‏ ‏.‏ قَالَ فَأَخَذَتْهُمْ سَنَةٌ حَصَّتْ كُلَّ شَىْءٍ حَتَّى أَكَلُوا الْجُلُودَ وَالْمَيْتَةَ مِنَ الْجُوعِ وَيَنْظُرُ إِلَى السَّمَاءِ أَحَدُهُمْ فَيَرَى كَهَيْئَةِ الدُّخَانِ فَأَتَاهُ أَبُو سُفْيَانَ فَقَالَ يَا مُحَمَّدُ إِنَّكَ جِئْتَ تَأْمُرُ بِطَاعَةِ اللَّهِ وَبِصِلَةِ الرَّحِمِ وَإِنَّ قَوْمَكَ قَدْ هَلَكُوا فَادْعُ اللَّهَ لَهُمْ - قَالَ اللَّهُ عَزَّ وَجَلَّ ‏{‏ فَارْتَقِبْ يَوْمَ تَأْتِي السَّمَاءُ بِدُخَانٍ مُبِينٍ * يَغْشَى النَّاسَ هَذَا عَذَابٌ أَلِيمٌ‏}‏ إِلَى قَوْلِهِ ‏{‏ إِنَّكُمْ عَائِدُونَ‏}‏ ‏.‏ قَالَ أَفَيُكْشَفُ عَذَابُ الآخِرَةِ ‏{‏ يَوْمَ نَبْطِشُ الْبَطْشَةَ الْكُبْرَى إِنَّا مُنْتَقِمُونَ‏}‏ فَالْبَطْشَةُ يَوْمَ بَدْرٍ وَقَدْ مَضَتْ آيَةُ الدُّخَانِ وَالْبَطْشَةُ وَاللِّزَامُ وَآيَةُ الرُّومِ ‏.‏","v":[]}],"29":[{"c":"Jami` at-Tirmidhi","r":"Volume 5, Book 44, Hadith 3255","u":"https://quranx.com/Hadith/Tirmidhi/DarusSalam/Volume-5/Book-44/Hadith-3255","x":"Narrated Anas bin Malik:\n\nthat the Messenger of Allah (ﷺ) said: \"There is no believer except that he has two doors: A door through which his deeds ascend, and a door through which his sustenance descends. So when he dies they weep for him. That is the meaning of the saying of Allah, the Mighty and Sublime: And the heavens and the earth wept not for them, nor were they given respite (44:29).\"","ar":"حَدَّثَنَا الْحُسَيْنُ بْنُ حُرَيْثٍ، حَدَّثَنَا وَكِيعٌ، عَنْ مُوسَى بْنِ عُبَيْدَةَ، عَنْ يَزِيدَ بْنِ أَبَانَ، عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ قَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم ‏\"‏ مَا مِنْ مُؤْمِنٍ إِلاَّ وَلَهُ بَابَانِ بَابٌ يَصْعَدُ مِنْهُ عَمَلُهُ وَبَابٌ يَنْزِلُ مِنْهُ رِزْقُهُ فَإِذَا مَاتَ بَكَيَا عَلَيْهِ فَذَلِكَ قَوْلُهُ عَزَّ وَجَلَّ ‏(‏ فَمَا بَكَتْ عَلَيْهِمُ السَّمَاءُ وَالأَرْضُ وَمَا كَانُوا مُنْظَرِينَ ‏)‏ ‏.‏ قَالَ أَبُو عِيسَى هَذَا حَدِيثٌ غَرِيبٌ لاَ نَعْرِفُهُ مَرْفُوعًا إِلاَّ مِنْ هَذَا الْوَجْهِ ‏.‏ وَمُوسَى بْنُ عُبَيْدَةَ وَيَزِيدُ بْنُ أَبَانَ الرَّقَاشِيُّ يُضَعَّفَانِ فِي الْحَدِيثِ ‏.‏","v":[]}]};